import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";
import postgres from "https://deno.land/x/postgresjs@v3.4.5/mod.js";

/**
 * DDL delivery vehicle for app schema changes.
 *
 * The remote migration history does not match `supabase/migrations/`, so
 * `supabase db push` would replay destructive early migrations and must never
 * be run. Schema changes reach the live database the same way the rest of this
 * project's have: an admin-gated edge function that opens `SUPABASE_DB_URL` and
 * applies idempotent SQL.
 *
 * `SETUP_SQL` is generated from the migration list in
 * `tools/embed-schema-setup-sql.cjs` — add new migrations there and regenerate
 * rather than hand-editing the constant. Everything it carries is written to be
 * safely re-runnable, so applying it twice is a no-op.
 *
 * Both actions are admin-only. `setup` runs the DDL; `verify` is read-only and
 * reports whether it landed.
 */

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
const SUPABASE_DB_URL = Deno.env.get("SUPABASE_DB_URL") || "";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SETUP_SQL = "-- ---------------------------------------------------------------------------\r\n-- Collection time slots\r\n--\r\n-- Customers pick a two-hour window between 07:00 and 23:00 for the day their\r\n-- goods are collected; dispatch plans the route around those windows and, when\r\n-- it has to move somebody, owes them a WhatsApp or a phone call.\r\n--\r\n-- The whole feature hangs off knowing *when* a collection is, and that was not\r\n-- previously knowable in SQL: `collection_schedules.pickup_date` is free text\r\n-- and holds \"September 14th, 2026\", \"2026-08-04\" and \"04/08/2026\" side by side.\r\n-- Section A gives every schedule a real `date` alongside it so a reminder can\r\n-- be timed 48 hours out.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. A real date for every published schedule\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- `public.parse_schedule_date(p_text)` already exists (added by\r\n-- 20260810_driver_route_collections.sql) and is depended on by the driver\r\n-- collection-matching functions. It is reused here rather than redefined —\r\n-- redefining it under a different parameter name is what this migration first\r\n-- tried, and Postgres rightly refused with \"cannot change name of input\r\n-- parameter\". Verified against every format the live schedules actually use:\r\n-- \"September 14th, 2026\", \"2026-08-04\", \"May 7th, 2026\" and\r\n-- \"Thursday, 3 September 2026\" all parse correctly.\r\n--\r\n-- Known divergence, currently unexercised: it resolves \"04/08/2026\" through\r\n-- `::date` and so reads it as 8 April, where the apps' `parseCollectionDate`\r\n-- reads day/month and gets 4 August. No published schedule uses that format.\r\n-- Changing the shared function would move the driver matching too, so this is\r\n-- documented rather than \"fixed\" here.\r\n\r\nalter table public.collection_schedules add column if not exists pickup_on date;\r\n\r\ncreate or replace function public.sync_schedule_pickup_on()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin\r\n  new.pickup_on := public.parse_schedule_date(new.pickup_date);\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists collection_schedule_pickup_on on public.collection_schedules;\r\ncreate trigger collection_schedule_pickup_on\r\n  before insert or update of pickup_date on public.collection_schedules\r\n  for each row execute function public.sync_schedule_pickup_on();\r\n\r\nupdate public.collection_schedules\r\n   set pickup_on = public.parse_schedule_date(pickup_date)\r\n where pickup_on is distinct from public.parse_schedule_date(pickup_date);\r\n\r\ncreate index if not exists collection_schedules_pickup_on_idx on public.collection_schedules(pickup_on);\r\n\r\n-- The date a given booking is being collected on: the linked schedule when\r\n-- there is one, otherwise whatever the booking recorded for itself.\r\ncreate or replace function public.shipment_collection_date(p_schedule_id uuid, p_metadata jsonb)\r\nreturns date language sql stable set search_path = public as $$\r\n  select coalesce(\r\n    (select cs.pickup_on from public.collection_schedules cs where cs.id = p_schedule_id),\r\n    public.parse_schedule_date(p_metadata->'collection'->>'date')\r\n  )\r\n$$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. The slot itself\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.collection_slots (\r\n  id uuid primary key default gen_random_uuid(),\r\n  shipment_id uuid not null unique references public.shipments(id) on delete cascade,\r\n  user_id uuid references auth.users(id) on delete set null,\r\n  collection_date date,\r\n  route text,\r\n\r\n  -- What the customer asked for. `requested_flexible` is \"any time is fine\",\r\n  -- which is a real answer and not the same as never having replied.\r\n  requested_start time,\r\n  requested_end time,\r\n  requested_flexible boolean not null default false,\r\n  requested_at timestamptz,\r\n\r\n  -- What dispatch settled on once the route was sequenced.\r\n  dispatch_start time,\r\n  dispatch_end time,\r\n  dispatch_set_at timestamptz,\r\n  dispatch_set_by uuid references auth.users(id) on delete set null,\r\n  change_reason text,\r\n\r\n  -- Proof that somebody actually spoke to the customer about a change.\r\n  customer_informed_at timestamptz,\r\n  customer_informed_by uuid references auth.users(id) on delete set null,\r\n  customer_informed_via text check (customer_informed_via in ('whatsapp', 'call', 'sms', 'in_person')),\r\n  customer_informed_note text,\r\n\r\n  reminder_sent_at timestamptz,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists collection_slots_date_idx on public.collection_slots(collection_date);\r\ncreate index if not exists collection_slots_user_idx on public.collection_slots(user_id);\r\n\r\ndo $$ begin\r\n  alter table public.collection_slots add constraint collection_slot_requested_window\r\n    check (\r\n      requested_start is null or requested_end is null\r\n      or (requested_start >= time '07:00' and requested_end <= time '23:00' and requested_end > requested_start)\r\n    );\r\nexception when duplicate_object then null; end $$;\r\n\r\ndo $$ begin\r\n  alter table public.collection_slots add constraint collection_slot_dispatch_window\r\n    check (\r\n      dispatch_start is null or dispatch_end is null\r\n      or (dispatch_start >= time '07:00' and dispatch_end <= time '23:00' and dispatch_end > dispatch_start)\r\n    );\r\nexception when duplicate_object then null; end $$;\r\n\r\ncreate or replace function public.touch_collection_slot()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin new.updated_at := now(); return new; end $$;\r\n\r\ndrop trigger if exists collection_slots_touch on public.collection_slots;\r\ncreate trigger collection_slots_touch before update on public.collection_slots\r\n  for each row execute function public.touch_collection_slot();\r\n\r\nalter table public.collection_slots enable row level security;\r\n\r\n-- Customers read their own slot; every write goes through the RPCs below so the\r\n-- 07:00-23:00 rule and the \"who changed this\" trail cannot be sidestepped.\r\ndrop policy if exists \"Customers read own collection slot\" on public.collection_slots;\r\ncreate policy \"Customers read own collection slot\" on public.collection_slots\r\n  for select to authenticated using (user_id = auth.uid());\r\n\r\ndrop policy if exists \"Operations manage collection slots\" on public.collection_slots;\r\ncreate policy \"Operations manage collection slots\" on public.collection_slots\r\n  for all to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\n-- A driver working the stop needs to know when the customer said they would be\r\n-- in, without being able to see anybody else's day.\r\ndrop policy if exists \"Drivers read slots on their runs\" on public.collection_slots;\r\ncreate policy \"Drivers read slots on their runs\" on public.collection_slots\r\n  for select to authenticated using (\r\n    exists (\r\n      select 1 from public.driver_run_stops st\r\n      join public.driver_runs r on r.id = st.run_id\r\n      where st.shipment_id = collection_slots.shipment_id and r.driver_id = auth.uid()\r\n    )\r\n  );\r\n\r\n-- Make sure a row exists for a booking, filling in the date and route from the\r\n-- booking itself. Returns the row id.\r\ncreate or replace function public.ensure_collection_slot(p_shipment_id uuid)\r\nreturns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare v_ship public.shipments%rowtype; v_date date; v_route text; v_id uuid;\r\nbegin\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found then raise exception 'Shipment not found'; end if;\r\n\r\n  v_date := public.shipment_collection_date(v_ship.collection_schedule_id, v_ship.metadata);\r\n  v_route := coalesce(\r\n    (select cs.route from public.collection_schedules cs where cs.id = v_ship.collection_schedule_id),\r\n    nullif(v_ship.metadata->'collection'->>'route', 'To be assigned'));\r\n\r\n  insert into public.collection_slots (shipment_id, user_id, collection_date, route)\r\n  values (p_shipment_id, v_ship.user_id, v_date, v_route)\r\n  on conflict (shipment_id) do update\r\n    set collection_date = coalesce(excluded.collection_date, collection_slots.collection_date),\r\n        route = coalesce(excluded.route, collection_slots.route),\r\n        user_id = coalesce(collection_slots.user_id, excluded.user_id)\r\n  returning id into v_id;\r\n  return v_id;\r\nend $$;\r\n\r\nrevoke all on function public.ensure_collection_slot(uuid) from public, anon, authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. The customer's half\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The customer confirms when they will be in. Passing p_flexible skips the\r\n * window entirely and tells dispatch any time on the day suits.\r\n */\r\ncreate or replace function public.confirm_collection_slot(\r\n  p_shipment_id uuid,\r\n  p_start time default null,\r\n  p_end time default null,\r\n  p_flexible boolean default false\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_ship public.shipments%rowtype; v_slot public.collection_slots%rowtype;\r\nbegin\r\n  if auth.uid() is null then raise exception 'Sign in to confirm your collection time'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found or v_ship.user_id is distinct from auth.uid() then\r\n    raise exception 'That booking is not yours';\r\n  end if;\r\n  if coalesce(v_ship.collection_status, 'Awaiting Collection') = 'Collected' then\r\n    raise exception 'This shipment has already been collected';\r\n  end if;\r\n\r\n  if not p_flexible then\r\n    if p_start is null or p_end is null then raise exception 'Choose a collection window'; end if;\r\n    if p_start < time '07:00' or p_end > time '23:00' or p_end <= p_start then\r\n      raise exception 'Collection windows run between 07:00 and 23:00';\r\n    end if;\r\n  end if;\r\n\r\n  perform public.ensure_collection_slot(p_shipment_id);\r\n\r\n  update public.collection_slots set\r\n    requested_start = case when p_flexible then null else p_start end,\r\n    requested_end = case when p_flexible then null else p_end end,\r\n    requested_flexible = p_flexible,\r\n    requested_at = now()\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  return to_jsonb(v_slot);\r\nend $$;\r\n\r\nrevoke all on function public.confirm_collection_slot(uuid, time, time, boolean) from public, anon;\r\ngrant execute on function public.confirm_collection_slot(uuid, time, time, boolean) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Dispatch's half\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Dispatch records the window it can actually work to. When that differs from\r\n * what the customer asked for, the customer is notified in the app straight\r\n * away — but an in-app notice is not a conversation, so the slot is left\r\n * flagged until somebody records a WhatsApp or a call against it.\r\n */\r\ncreate or replace function public.dispatch_set_collection_slot(\r\n  p_shipment_id uuid,\r\n  p_start time,\r\n  p_end time,\r\n  p_reason text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_slot public.collection_slots%rowtype; v_ship public.shipments%rowtype; v_moved boolean;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can set collection windows'; end if;\r\n  if p_start is null or p_end is null then raise exception 'A dispatch window needs a start and an end'; end if;\r\n  if p_start < time '07:00' or p_end > time '23:00' or p_end <= p_start then\r\n    raise exception 'Collection windows run between 07:00 and 23:00';\r\n  end if;\r\n\r\n  perform public.ensure_collection_slot(p_shipment_id);\r\n  select * into v_slot from public.collection_slots where shipment_id = p_shipment_id;\r\n\r\n  -- \"Moved\" means moved away from something the customer actually asked for.\r\n  -- A customer who said any time is fine, or who never replied, has not been\r\n  -- moved and generates no obligation.\r\n  v_moved := v_slot.requested_at is not null\r\n         and not v_slot.requested_flexible\r\n         and (v_slot.requested_start is distinct from p_start or v_slot.requested_end is distinct from p_end);\r\n\r\n  update public.collection_slots set\r\n    dispatch_start = p_start,\r\n    dispatch_end = p_end,\r\n    dispatch_set_at = now(),\r\n    dispatch_set_by = auth.uid(),\r\n    change_reason = nullif(btrim(coalesce(p_reason, '')), '')\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  if v_moved then\r\n    select * into v_ship from public.shipments where id = p_shipment_id;\r\n    if v_ship.user_id is not null then\r\n      insert into public.notifications (user_id, title, message, type, related_id)\r\n      values (\r\n        v_ship.user_id,\r\n        'Your collection time has changed',\r\n        coalesce(v_ship.customer_reference, v_ship.tracking_number)\r\n          || ': we now plan to collect between ' || substring(p_start::text from 1 for 5)\r\n          || ' and ' || substring(p_end::text from 1 for 5)\r\n          || coalesce(' on ' || to_char(v_slot.collection_date, 'FMDay FMDD FMMonth'), '')\r\n          || '.' || coalesce(' ' || v_slot.change_reason, ''),\r\n        'shipment',\r\n        p_shipment_id);\r\n    end if;\r\n  end if;\r\n\r\n  return to_jsonb(v_slot) || jsonb_build_object('moved', v_moved);\r\nend $$;\r\n\r\nrevoke all on function public.dispatch_set_collection_slot(uuid, time, time, text) from public, anon;\r\ngrant execute on function public.dispatch_set_collection_slot(uuid, time, time, text) to authenticated;\r\n\r\n/** Records that somebody actually reached the customer about a change. */\r\ncreate or replace function public.mark_collection_customer_informed(\r\n  p_shipment_id uuid,\r\n  p_via text,\r\n  p_note text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_slot public.collection_slots%rowtype;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can close a customer contact'; end if;\r\n  if p_via not in ('whatsapp', 'call', 'sms', 'in_person') then raise exception 'Unknown contact method'; end if;\r\n\r\n  update public.collection_slots set\r\n    customer_informed_at = now(),\r\n    customer_informed_by = auth.uid(),\r\n    customer_informed_via = p_via,\r\n    customer_informed_note = nullif(btrim(coalesce(p_note, '')), '')\r\n  where shipment_id = p_shipment_id\r\n  returning * into v_slot;\r\n\r\n  if not found then raise exception 'No collection slot for that booking'; end if;\r\n  return to_jsonb(v_slot);\r\nend $$;\r\n\r\nrevoke all on function public.mark_collection_customer_informed(uuid, text, text) from public, anon;\r\ngrant execute on function public.mark_collection_customer_informed(uuid, text, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. The 48-hour reminder\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Two days before a collection, offer everybody booked onto it a window.\r\n *\r\n * The offer is optional and the wording says so: a customer who ignores it is\r\n * not chased again and is not treated as a problem, because dispatch plans the\r\n * round perfectly well without an answer. `reminder_sent_at` makes this\r\n * once-only per booking, so a retry or a second run on the same day cannot\r\n * message anyone twice.\r\n */\r\ncreate or replace function public.queue_collection_slot_reminders()\r\nreturns integer language plpgsql security definer set search_path = public as $$\r\ndeclare v_target date := current_date + 2; v_count integer := 0; v_row record;\r\nbegin\r\n  for v_row in\r\n    select s.id, s.user_id, s.customer_reference, s.tracking_number,\r\n           public.shipment_collection_date(s.collection_schedule_id, s.metadata) as collect_on\r\n      from public.shipments s\r\n     where s.deleted_at is null\r\n       and s.user_id is not null\r\n       and coalesce(s.collection_status, 'Awaiting Collection') <> 'Collected'\r\n       and public.shipment_collection_date(s.collection_schedule_id, s.metadata) = v_target\r\n       and coalesce((select (p.notification_preferences->>'shipment')::boolean\r\n                       from public.profiles p where p.id = s.user_id), true)\r\n       and not exists (\r\n         select 1 from public.collection_slots cs\r\n          where cs.shipment_id = s.id and cs.reminder_sent_at is not null)\r\n  loop\r\n    perform public.ensure_collection_slot(v_row.id);\r\n\r\n    insert into public.notifications (user_id, title, message, type, related_id)\r\n    values (\r\n      v_row.user_id,\r\n      'Your collection is in two days',\r\n      coalesce(v_row.customer_reference, v_row.tracking_number)\r\n        || ' is being collected on ' || to_char(v_row.collect_on, 'FMDay FMDD FMMonth')\r\n        || '. If a particular time suits you better, pick a two-hour window between 7am and 11pm in the app —'\r\n        || ' otherwise the driver will call ahead on the day.',\r\n      'shipment',\r\n      v_row.id);\r\n\r\n    update public.collection_slots set reminder_sent_at = now() where shipment_id = v_row.id;\r\n    v_count := v_count + 1;\r\n  end loop;\r\n\r\n  return v_count;\r\nend $$;\r\n\r\nrevoke all on function public.queue_collection_slot_reminders() from public, anon, authenticated;\r\ngrant execute on function public.queue_collection_slot_reminders() to service_role;\r\n\r\n-- 08:00 UTC daily: a Saturday collection asks on Thursday morning, which leaves\r\n-- two working days for dispatch to react to the answers.\r\ndo $$ begin create extension if not exists pg_cron; exception when others then null; end $$;\r\ndo $$\r\nbegin\r\n  if exists (select 1 from pg_extension where extname = 'pg_cron') then\r\n    perform cron.unschedule(jobid) from cron.job where jobname = 'collection-slot-reminders';\r\n    perform cron.schedule(\r\n      'collection-slot-reminders',\r\n      '0 8 * * *',\r\n      $job$select public.queue_collection_slot_reminders();$job$);\r\n  end if;\r\nexception when others then null;\r\nend $$;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Saved pickup addresses, and buying drums from us\r\n--\r\n-- Two things customers could not do from the app:\r\n--\r\n--   1. Save the address we collect FROM. Saved addresses existed only for\r\n--      Zimbabwe delivery; the collection address lived as three loose columns\r\n--      on `profiles`, so a customer with two pickup addresses (home and their\r\n--      mother's) had to retype one of them on every booking.\r\n--   2. Buy a drum from us. The website has offered this for a while; the app\r\n--      never did, so app customers had to ask on WhatsApp.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Pickup addresses share the delivery-address table\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- One table, two kinds. The columns already fit both: for a pickup address the\r\n-- \"recipient\" is whoever hands the goods over, which is normally the customer.\r\n-- A separate table would have meant duplicating the RLS, the default handling\r\n-- and every screen that reads them.\r\nalter table public.customer_addresses\r\n  add column if not exists address_type text not null default 'delivery';\r\n\r\ndo $$ begin\r\n  alter table public.customer_addresses add constraint customer_address_type_check\r\n    check (address_type in ('delivery', 'pickup'));\r\nexception when duplicate_object then null; end $$;\r\n\r\n-- Everything that existed before this migration is a Zimbabwe delivery address.\r\nupdate public.customer_addresses set address_type = 'delivery' where address_type is null;\r\n\r\ncreate index if not exists customer_addresses_user_type_idx\r\n  on public.customer_addresses(user_id, address_type);\r\n\r\n/**\r\n * Give every customer who onboarded with a pickup address a saved pickup\r\n * address to match, so the feature is useful on first open rather than empty.\r\n *\r\n * Deliberately additive: the `profiles` columns are left exactly as they are,\r\n * because the website's booking form still reads them. This only ever inserts,\r\n * only for customers with no pickup address saved yet, so re-running it is a\r\n * no-op rather than a pile of duplicates.\r\n */\r\ninsert into public.customer_addresses (\r\n  user_id, address_type, recipient_name, recipient_phone,\r\n  address_line1, city, postal_code, country, is_default)\r\nselect\r\n  p.id,\r\n  'pickup',\r\n  coalesce(nullif(btrim(p.full_name), ''), 'Me'),\r\n  coalesce(p.phone_number, ''),\r\n  btrim(p.pickup_address),\r\n  coalesce(nullif(btrim(p.pickup_city), ''), ''),\r\n  p.postal_code,\r\n  case when lower(coalesce(p.country, '')) like '%ireland%' then 'Ireland' else 'United Kingdom' end,\r\n  true\r\nfrom public.profiles p\r\nwhere coalesce(btrim(p.pickup_address), '') <> ''\r\n  and not exists (\r\n    select 1 from public.customer_addresses a\r\n     where a.user_id = p.id and a.address_type = 'pickup');\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Buying drums from us\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- The purchase prices are the same number in either currency, matching how the\r\n-- collection and door-delivery fees already work (GBP 25 / EUR 25).\r\nupdate public.app_configuration\r\n   set value = value\r\n     || jsonb_build_object('metalDrumPurchase', coalesce((value->>'metalDrumPurchase')::numeric, 40))\r\n     || jsonb_build_object('plasticDrumPurchase', coalesce((value->>'plasticDrumPurchase')::numeric, 50))\r\n where key = 'booking_fees';\r\n\r\n-- Step aside so the current booking function can be wrapped rather than\r\n-- rewritten. Guarded on the target name, exactly as the earlier booking\r\n-- migrations did it, so re-running this file renames nothing a second time.\r\ndo $$ begin\r\n  if to_regprocedure('public.create_customer_booking_v2(jsonb)') is null then\r\n    execute 'alter function public.create_customer_booking(jsonb) rename to create_customer_booking_v2';\r\n  end if;\r\nend $$;\r\n\r\n/**\r\n * Price purchased drums server-side, like everything else on a booking.\r\n *\r\n * This wraps the wrapper: `create_customer_booking` already delegates the bulk\r\n * of the work to `create_customer_booking_legacy` and then corrects the invoice\r\n * for door delivery and quote items. Purchased drums are appended the same way,\r\n * at the fee held in `app_configuration` rather than anything the client sent —\r\n * a client that asks for cheap drums gets charged the configured price.\r\n */\r\ncreate or replace function public.create_customer_booking(p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_result jsonb; v_shipment_id uuid; v_ship public.shipments%rowtype;\r\n  v_invoice jsonb; v_meta jsonb; v_lines jsonb; v_total numeric;\r\n  v_drum_type text; v_drum_qty integer; v_drum_price numeric; v_drum_label text;\r\nbegin\r\n  -- Everything the previous version did stays exactly as it was.\r\n  v_result := public.create_customer_booking_v2(p);\r\n\r\n  v_drum_type := nullif(p->'purchaseDrums'->>'type', '');\r\n  v_drum_qty := greatest(0, coalesce((p->'purchaseDrums'->>'quantity')::integer, 0));\r\n  if v_drum_type is null or v_drum_qty = 0 then return v_result; end if;\r\n  if v_drum_type not in ('metal', 'plastic') then raise exception 'Unknown drum type'; end if;\r\n\r\n  v_drum_price := public.config_number('booking_fees',\r\n    case when v_drum_type = 'metal' then 'metalDrumPurchase' else 'plasticDrumPurchase' end, 0);\r\n  if v_drum_price <= 0 then return v_result; end if;\r\n\r\n  v_drum_label := case when v_drum_type = 'metal' then 'Metal drum purchased from us' else 'Plastic barrel purchased from us' end;\r\n\r\n  v_shipment_id := (v_result->>'id')::uuid;\r\n  select * into v_ship from public.shipments where id = v_shipment_id for update;\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n  v_lines := coalesce(v_invoice->'items', '[]'::jsonb)\r\n    || jsonb_build_array(jsonb_build_object(\r\n         'description', v_drum_label, 'quantity', v_drum_qty, 'unitPrice', v_drum_price));\r\n  v_total := coalesce((v_result->>'estimatedTotal')::numeric, 0) + (v_drum_qty * v_drum_price);\r\n\r\n  v_invoice := jsonb_set(v_invoice, '{items}', v_lines, true);\r\n  v_meta := jsonb_set(coalesce(v_ship.metadata, '{}'::jsonb), '{invoice}', v_invoice, true);\r\n  v_meta := jsonb_set(v_meta, '{pricing,estimatedTotal}', to_jsonb(v_total), true);\r\n  -- Same shape the website writes, so warehouse and finance read one format.\r\n  v_meta := jsonb_set(v_meta, '{purchasedDrums}', jsonb_build_object(\r\n    'type', v_drum_type, 'quantity', v_drum_qty,\r\n    'priceEach', v_drum_price, 'totalPrice', v_drum_qty * v_drum_price), true);\r\n\r\n  update public.shipments set metadata = v_meta where id = v_shipment_id;\r\n  return v_result || jsonb_build_object('estimatedTotal', v_total, 'invoice', v_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Collection runs: giving a collection period an identity\r\n--\r\n-- Dispatch could not group work by \"the Northampton run on the 14th\" because\r\n-- nothing in the database represented that. `collection_schedules` holds one\r\n-- row per ROUTE and its `pickup_date` is edited in place\r\n-- (`update ... set pickup_date = new_date where route = route_name`), so the\r\n-- schedule id identifies a route, not an occurrence of it: move the date and\r\n-- every shipment ever linked to that route appears to belong to the new date.\r\n--\r\n-- The shape of the problem in the live data before this migration:\r\n--   * 278 shipments read as awaiting collection, of which only 11 carried a\r\n--     schedule link at all.\r\n--   * 83 distinct route/date pairs, dominated by \"(no route) | (no date)\" (71)\r\n--     and \"To be assigned | To be confirmed\" (35).\r\n--   * Route names recorded inconsistently — BRIGHTON vs BRIGHTON ROUTE, LEEDS\r\n--     vs LEEDS ROUTE, SOUTHEND vs SOUTHEND ROUTE.\r\n--\r\n-- A `collection_run` is one route on one date. Shipments attach to it\r\n-- automatically as they are booked, whichever booking path they came in\r\n-- through, and dispatch opens a run to work it.\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. The run\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.collection_runs (\r\n  id uuid primary key default gen_random_uuid(),\r\n  schedule_id uuid references public.collection_schedules(id) on delete set null,\r\n  route text not null,\r\n  country text,\r\n  -- Null while the office has not published the next date for this route. The\r\n  -- run still exists and still gathers bookings; it simply has no date yet.\r\n  collection_date date,\r\n  status text not null default 'planned'\r\n    check (status in ('planned', 'active', 'completed', 'cancelled')),\r\n  driver_run_id uuid references public.driver_runs(id) on delete set null,\r\n  notes text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- One run per route per date. Nulls compare as distinct in a plain unique\r\n-- index, so the undated run is pinned to a sentinel to keep it single.\r\ncreate unique index if not exists collection_runs_route_date_key\r\n  on public.collection_runs (route, coalesce(collection_date, date '0001-01-01'));\r\ncreate index if not exists collection_runs_date_idx on public.collection_runs (collection_date);\r\ncreate index if not exists collection_runs_status_idx on public.collection_runs (status);\r\n\r\nalter table public.shipments\r\n  add column if not exists collection_run_id uuid references public.collection_runs(id) on delete set null;\r\ncreate index if not exists shipments_collection_run_idx\r\n  on public.shipments (collection_run_id) where deleted_at is null;\r\n\r\ncreate or replace function public.touch_collection_run()\r\nreturns trigger language plpgsql set search_path = public as $$\r\nbegin new.updated_at := now(); return new; end $$;\r\n\r\ndrop trigger if exists collection_runs_touch on public.collection_runs;\r\ncreate trigger collection_runs_touch before update on public.collection_runs\r\n  for each row execute function public.touch_collection_run();\r\n\r\nalter table public.collection_runs enable row level security;\r\n\r\ndrop policy if exists \"Operations manage collection runs\" on public.collection_runs;\r\ncreate policy \"Operations manage collection runs\" on public.collection_runs\r\n  for all to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\n-- A driver working the run needs to see it.\r\ndrop policy if exists \"Drivers read their collection runs\" on public.collection_runs;\r\ncreate policy \"Drivers read their collection runs\" on public.collection_runs\r\n  for select to authenticated using (\r\n    exists (select 1 from public.driver_runs r\r\n             where r.id = collection_runs.driver_run_id and r.driver_id = auth.uid()));\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Working out which route a booking belongs to\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The canonical route name for whatever was recorded on a booking.\r\n *\r\n * Bookings carry \"BRIGHTON\" where the schedule says \"BRIGHTON ROUTE\" and vice\r\n * versa, so an exact match loses roughly a fifth of them. Compared on letters\r\n * and digits only, with the word ROUTE stripped from both sides.\r\n */\r\ncreate or replace function public.canonical_route_name(p_route text)\r\nreturns text language sql stable set search_path = public as $$\r\n  select cs.route from public.collection_schedules cs\r\n   where regexp_replace(upper(regexp_replace(coalesce(cs.route, ''), '[^A-Za-z0-9]', '', 'g')), 'ROUTE$', '')\r\n       = regexp_replace(upper(regexp_replace(coalesce(p_route, ''), '[^A-Za-z0-9]', '', 'g')), 'ROUTE$', '')\r\n     and coalesce(p_route, '') <> ''\r\n   limit 1\r\n$$;\r\n\r\n/**\r\n * The schedule covering a collection address, mirroring the apps'\r\n * `scheduleMatchesPostcode`.\r\n *\r\n * UK matches the postcode's outward code or the town against the route's areas;\r\n * Ireland has no usable postcode so it matches the town alone. Deliberately\r\n * returns nothing rather than a guess when neither matches — an unassigned\r\n * booking that dispatch can see is far better than a confident wrong route.\r\n */\r\ncreate or replace function public.match_collection_schedule(\r\n  p_postcode text, p_city text, p_country text\r\n) returns public.collection_schedules\r\nlanguage plpgsql stable set search_path = public as $$\r\ndeclare\r\n  v_ireland boolean := lower(coalesce(p_country, '')) like '%ireland%';\r\n  v_code text := upper(regexp_replace(coalesce(p_postcode, ''), '[^A-Za-z0-9]', '', 'g'));\r\n  v_town text := upper(regexp_replace(coalesce(p_city, ''), '[^A-Za-z0-9]', '', 'g'));\r\n  v_outward text;\r\n  v_row public.collection_schedules%rowtype;\r\nbegin\r\n  -- \"LU11AA\" -> \"LU1\"; anything four characters or shorter is already outward.\r\n  v_outward := case when length(v_code) > 4 then left(v_code, length(v_code) - 3) else v_code end;\r\n\r\n  if v_ireland then\r\n    if length(v_town) < 3 then return null; end if;\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, '')) like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_town || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    return v_row;\r\n  end if;\r\n\r\n  if length(v_outward) >= 2 then\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, 'UK')) not like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_outward || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    if found then return v_row; end if;\r\n  end if;\r\n\r\n  if length(v_town) >= 3 then\r\n    select * into v_row from public.collection_schedules cs\r\n     where lower(coalesce(cs.country, 'UK')) not like '%ireland%'\r\n       and upper(regexp_replace(cs.areas::text, '[^A-Za-z0-9]', '', 'g')) like '%' || v_town || '%'\r\n     order by cs.pickup_on nulls last limit 1;\r\n    return v_row;\r\n  end if;\r\n\r\n  return null;\r\nend $$;\r\n\r\n/** Find or create the run for one route on one date. */\r\ncreate or replace function public.ensure_collection_run(\r\n  p_route text, p_date date, p_schedule_id uuid default null, p_country text default null\r\n) returns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare v_id uuid;\r\nbegin\r\n  if coalesce(btrim(p_route), '') = '' then return null; end if;\r\n\r\n  select id into v_id from public.collection_runs\r\n   where route = p_route and coalesce(collection_date, date '0001-01-01') = coalesce(p_date, date '0001-01-01');\r\n  if found then\r\n    update public.collection_runs\r\n       set schedule_id = coalesce(schedule_id, p_schedule_id),\r\n           country = coalesce(country, p_country)\r\n     where id = v_id;\r\n    return v_id;\r\n  end if;\r\n\r\n  insert into public.collection_runs (schedule_id, route, country, collection_date)\r\n  values (p_schedule_id, p_route, p_country, p_date)\r\n  on conflict do nothing\r\n  returning id into v_id;\r\n\r\n  if v_id is null then\r\n    select id into v_id from public.collection_runs\r\n     where route = p_route and coalesce(collection_date, date '0001-01-01') = coalesce(p_date, date '0001-01-01');\r\n  end if;\r\n  return v_id;\r\nend $$;\r\n\r\nrevoke all on function public.ensure_collection_run(text, date, uuid, text) from public, anon, authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Attaching a booking to its run\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Put one shipment in the right run.\r\n *\r\n * Order of preference for the route: the schedule already linked to the\r\n * booking, then the route name the booking recorded (canonicalised), then the\r\n * route the collection postcode resolves to. The date follows the route's\r\n * published date, falling back to whatever the booking recorded.\r\n *\r\n * Returns the run id, or null when nothing could be resolved — which is a\r\n * legitimate outcome and shows in dispatch as unassigned.\r\n */\r\ncreate or replace function public.attach_shipment_to_run(p_shipment_id uuid)\r\nreturns uuid language plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_ship public.shipments%rowtype;\r\n  v_sched public.collection_schedules%rowtype;\r\n  v_sender jsonb; v_route text; v_date date; v_run uuid;\r\nbegin\r\n  select * into v_ship from public.shipments where id = p_shipment_id;\r\n  if not found then return null; end if;\r\n\r\n  if v_ship.collection_schedule_id is not null then\r\n    select * into v_sched from public.collection_schedules where id = v_ship.collection_schedule_id;\r\n  end if;\r\n\r\n  if v_sched.id is null then\r\n    v_route := public.canonical_route_name(nullif(v_ship.metadata->'collection'->>'route', 'To be assigned'));\r\n    if v_route is not null then\r\n      select * into v_sched from public.collection_schedules where route = v_route limit 1;\r\n    end if;\r\n  end if;\r\n\r\n  if v_sched.id is null then\r\n    v_sender := coalesce(v_ship.metadata->'sender', v_ship.metadata->'senderDetails', '{}'::jsonb);\r\n    select * into v_sched from public.match_collection_schedule(\r\n      coalesce(v_sender->>'postalCode', v_sender->>'postcode'),\r\n      v_sender->>'city',\r\n      coalesce(v_sender->>'country', v_ship.metadata->'collection'->>'country'));\r\n  end if;\r\n\r\n  if v_sched.id is null then return null; end if;\r\n\r\n  v_date := coalesce(v_sched.pickup_on, public.parse_schedule_date(v_ship.metadata->'collection'->>'date'));\r\n  v_run := public.ensure_collection_run(v_sched.route, v_date, v_sched.id, v_sched.country);\r\n\r\n  update public.shipments\r\n     set collection_run_id = v_run,\r\n         collection_schedule_id = coalesce(collection_schedule_id, v_sched.id)\r\n   where id = p_shipment_id;\r\n\r\n  return v_run;\r\nend $$;\r\n\r\nrevoke all on function public.attach_shipment_to_run(uuid) from public, anon;\r\ngrant execute on function public.attach_shipment_to_run(uuid) to authenticated;\r\n\r\n/**\r\n * Every new booking joins a run, whichever door it came in through — the app,\r\n * the website, or a manual booking typed by the office. A trigger rather than a\r\n * change to `create_customer_booking`, because there is more than one creator\r\n * and they must not drift apart again.\r\n *\r\n * Never fatal: a booking that cannot be filed is still a booking.\r\n */\r\ncreate or replace function public.attach_new_shipment_to_run()\r\nreturns trigger language plpgsql security definer set search_path = public as $$\r\nbegin\r\n  begin\r\n    perform public.attach_shipment_to_run(new.id);\r\n  exception when others then\r\n    null;\r\n  end;\r\n  return null;\r\nend $$;\r\n\r\ndrop trigger if exists shipment_joins_collection_run on public.shipments;\r\ncreate trigger shipment_joins_collection_run\r\n  after insert on public.shipments\r\n  for each row execute function public.attach_new_shipment_to_run();\r\n\r\n/**\r\n * When the office moves a route's date, the run moves with it.\r\n *\r\n * Without this, editing NORTHAMPTON from the 14th to the 16th would leave the\r\n * existing bookings in a 14th run and start filing new ones into a 16th run —\r\n * splitting one collection into two groups, which is precisely the confusion\r\n * this table exists to remove. Only open runs follow; a completed run keeps the\r\n * date it actually happened on.\r\n */\r\ncreate or replace function public.move_collection_run_with_schedule()\r\nreturns trigger language plpgsql security definer set search_path = public as $$\r\nbegin\r\n  if new.pickup_on is distinct from old.pickup_on then\r\n    -- Skip when a run already sits on the new date, or the unique index trips.\r\n    update public.collection_runs r\r\n       set collection_date = new.pickup_on\r\n     where r.schedule_id = new.id\r\n       and r.status in ('planned', 'active')\r\n       and r.collection_date is distinct from new.pickup_on\r\n       and not exists (\r\n         select 1 from public.collection_runs other\r\n          where other.route = r.route and other.id <> r.id\r\n            and coalesce(other.collection_date, date '0001-01-01') = coalesce(new.pickup_on, date '0001-01-01'));\r\n  end if;\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists collection_run_follows_schedule on public.collection_schedules;\r\ncreate trigger collection_run_follows_schedule\r\n  after update of pickup_on on public.collection_schedules\r\n  for each row execute function public.move_collection_run_with_schedule();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Backfill\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * File the bookings that are genuinely still waiting to be collected.\r\n *\r\n * Scoped hard on purpose. `collection_status` is stale across this data — 124\r\n * of the 278 shipments it calls uncollected are already In Transit, Arrived or\r\n * Delivered — so `status` is the signal that means anything, and only the\r\n * pre-collection ones are swept in. Sixty days keeps a year of abandoned\r\n * bookings out of next week's run.\r\n */\r\ndo $$\r\ndeclare v_row record; v_count integer := 0;\r\nbegin\r\n  for v_row in\r\n    select s.id from public.shipments s\r\n     where s.deleted_at is null\r\n       and s.collection_run_id is null\r\n       and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n       and s.created_at >= now() - interval '60 days'\r\n  loop\r\n    begin\r\n      perform public.attach_shipment_to_run(v_row.id);\r\n      v_count := v_count + 1;\r\n    exception when others then null;\r\n    end;\r\n  end loop;\r\n  raise notice 'collection runs: considered % pending shipments', v_count;\r\nend $$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. The dispatch board\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * One row per run, with the numbers dispatch actually decides on: how much work\r\n * is in it, how many customers have chosen a time, and whether a driver is on\r\n * it yet. Unassigned bookings are returned as a synthetic run with a null id so\r\n * they sit in the same list rather than being forgotten in another screen.\r\n */\r\ncreate or replace function public.collection_run_board(p_include_done boolean default false)\r\nreturns table (\r\n  run_id uuid, route text, country text, collection_date date, status text,\r\n  driver_run_id uuid, driver_name text,\r\n  shipment_count integer, slots_chosen integer, needs_contact integer\r\n) language sql stable security definer set search_path = public as $$\r\n  select\r\n    r.id, r.route, r.country, r.collection_date, r.status,\r\n    r.driver_run_id,\r\n    -- Not every staff profile has a name filled in, and a nameless driver\r\n    -- must not read as no driver at all.\r\n    (select coalesce(nullif(btrim(p.full_name), ''), p.email) from public.profiles p\r\n      join public.driver_runs dr on dr.driver_id = p.id where dr.id = r.driver_run_id),\r\n    (select count(*)::int from public.shipments s\r\n      where s.collection_run_id = r.id and s.deleted_at is null),\r\n    (select count(*)::int from public.shipments s\r\n      join public.collection_slots cs on cs.shipment_id = s.id\r\n      where s.collection_run_id = r.id and s.deleted_at is null and cs.requested_at is not null),\r\n    (select count(*)::int from public.shipments s\r\n      join public.collection_slots cs on cs.shipment_id = s.id\r\n      where s.collection_run_id = r.id and s.deleted_at is null\r\n        and cs.dispatch_set_at is not null\r\n        and not cs.requested_flexible and cs.requested_at is not null\r\n        and (cs.requested_start is distinct from cs.dispatch_start\r\n          or cs.requested_end is distinct from cs.dispatch_end)\r\n        and (cs.customer_informed_at is null or cs.customer_informed_at < cs.dispatch_set_at))\r\n  from public.collection_runs r\r\n  where public.is_operations_admin()\r\n    and (p_include_done or r.status in ('planned', 'active'))\r\n\r\n  union all\r\n\r\n  -- Recent bookings whose postcode matched no route. These need a human, so\r\n  -- they sit in the same list rather than in a screen nobody opens.\r\n  select\r\n    null::uuid, 'Unassigned', null, null, 'planned', null, null,\r\n    (select count(*)::int from public.shipments s\r\n      where s.deleted_at is null and s.collection_run_id is null\r\n        and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n        and s.created_at >= now() - interval '60 days'),\r\n    0, 0\r\n  where public.is_operations_admin()\r\n\r\n  union all\r\n\r\n  -- Older pending bookings, counted but kept out of the working set. Most are\r\n  -- abandoned; burying this week's real stragglers among a year of them was\r\n  -- what made the flat list unusable in the first place.\r\n  select\r\n    null::uuid, 'Older than 60 days', null, null, 'planned', null, null,\r\n    (select count(*)::int from public.shipments s\r\n      where s.deleted_at is null and s.collection_run_id is null\r\n        and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n        and s.created_at < now() - interval '60 days'),\r\n    0, 0\r\n  where public.is_operations_admin()\r\n\r\n  order by 4 nulls last, 2\r\n$$;\r\n\r\nrevoke all on function public.collection_run_board(boolean) from public, anon;\r\ngrant execute on function public.collection_run_board(boolean) to authenticated;\r\n\n\n-- ---------------------------------------------------------------------------\r\n-- Assigning a driver to a whole collection group\r\n--\r\n-- The group already is the route: everything collecting on the Northampton run\r\n-- on the 14th. Making dispatch re-pick those same shipments one by one in the\r\n-- route builder just to name a driver was the remaining piece of busywork, so\r\n-- this does the whole thing in one call — create or reuse the driver's run for\r\n-- that day, put every collection in the group on it, order the stops by the\r\n-- windows customers actually asked for, and tie the group to the run.\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Put a driver on a collection group.\r\n *\r\n * Passing a null driver unassigns the group and cancels the run it created,\r\n * which is what dispatch wants when a driver calls in sick and the work has to\r\n * go back in the pool.\r\n *\r\n * Stops are ordered by the customer's requested window, earliest first, with\r\n * everyone who did not choose one after them. That is the whole point of asking\r\n * for windows: a route sequenced against them is a route that keeps its\r\n * promises. Where a customer chose a window it is also recorded as the dispatch\r\n * window, so the run reads as agreed rather than as an unanswered question —\r\n * and because it matches what they asked for, nobody is flagged as moved and\r\n * nobody is owed a phone call.\r\n */\r\ncreate or replace function public.assign_collection_run_driver(\r\n  p_run_id uuid,\r\n  p_driver_id uuid,\r\n  p_vehicle text default null\r\n) returns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_run public.collection_runs%rowtype;\r\n  v_driver_run public.driver_runs%rowtype;\r\n  v_driver_run_id uuid;\r\n  v_order integer;\r\n  v_added integer := 0;\r\n  v_row record;\r\n  v_sender jsonb;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Only dispatch can assign a driver'; end if;\r\n\r\n  select * into v_run from public.collection_runs where id = p_run_id for update;\r\n  if not found then raise exception 'Collection group not found'; end if;\r\n\r\n  -- Unassign.\r\n  if p_driver_id is null then\r\n    if v_run.driver_run_id is not null then\r\n      update public.driver_runs set status = 'cancelled', updated_at = now()\r\n       where id = v_run.driver_run_id and status <> 'completed';\r\n      update public.shipments set assigned_driver_id = null\r\n       where collection_run_id = p_run_id and deleted_at is null;\r\n    end if;\r\n    update public.collection_runs\r\n       set driver_run_id = null, status = 'planned' where id = p_run_id;\r\n    return jsonb_build_object('assigned', false, 'stops', 0);\r\n  end if;\r\n\r\n  -- A driver run is filed by date, so an undated group has nothing to file\r\n  -- against. Publishing the route's date is the fix, and saying so is more use\r\n  -- than a constraint violation.\r\n  if v_run.collection_date is null then\r\n    raise exception 'Publish a collection date for % before assigning a driver', v_run.route;\r\n  end if;\r\n\r\n  -- One run per driver per day is a database rule, so reuse theirs if it exists.\r\n  select * into v_driver_run from public.driver_runs\r\n   where driver_id = p_driver_id and run_date = v_run.collection_date;\r\n\r\n  if found then\r\n    v_driver_run_id := v_driver_run.id;\r\n    if v_driver_run.status = 'completed' then\r\n      raise exception 'That driver has already completed their run for this day';\r\n    end if;\r\n    update public.driver_runs\r\n       set route_name = coalesce(route_name, v_run.route),\r\n           vehicle_label = coalesce(p_vehicle, vehicle_label),\r\n           status = case when status = 'cancelled' then 'planned' else status end,\r\n           updated_at = now()\r\n     where id = v_driver_run_id;\r\n  else\r\n    insert into public.driver_runs (driver_id, run_date, status, run_type, route_name, vehicle_label, created_by)\r\n    values (p_driver_id, v_run.collection_date, 'planned', 'pickup', v_run.route, p_vehicle, auth.uid())\r\n    returning id into v_driver_run_id;\r\n  end if;\r\n\r\n  -- Moving the group to a different driver takes its existing stops along, so\r\n  -- nothing has to be rebuilt and no stop is orphaned on the old run.\r\n  if v_run.driver_run_id is not null and v_run.driver_run_id <> v_driver_run_id then\r\n    update public.driver_run_stops st\r\n       set run_id = v_driver_run_id,\r\n           stop_order = st.stop_order\r\n             + (select coalesce(max(stop_order), 0) from public.driver_run_stops where run_id = v_driver_run_id)\r\n     where st.run_id = v_run.driver_run_id\r\n       and st.shipment_id in (select id from public.shipments where collection_run_id = p_run_id)\r\n       and st.status not in ('completed', 'failed');\r\n    update public.driver_runs set status = 'cancelled', updated_at = now()\r\n     where id = v_run.driver_run_id\r\n       and not exists (select 1 from public.driver_run_stops where run_id = v_run.driver_run_id);\r\n  end if;\r\n\r\n  select coalesce(max(stop_order), 0) into v_order\r\n    from public.driver_run_stops where run_id = v_driver_run_id;\r\n\r\n  for v_row in\r\n    select s.id, s.metadata, s.pickup_latitude, s.pickup_longitude,\r\n           cs.requested_start, cs.requested_end, cs.requested_flexible, cs.requested_at\r\n      from public.shipments s\r\n      left join public.collection_slots cs on cs.shipment_id = s.id\r\n     where s.collection_run_id = p_run_id\r\n       and s.deleted_at is null\r\n       and lower(coalesce(s.status, '')) in ('booking confirmed', 'confirmed', 'pending')\r\n       and not exists (\r\n         select 1 from public.driver_run_stops st\r\n          where st.run_id = v_driver_run_id and st.shipment_id = s.id)\r\n     -- Earliest promised window first; everyone without one after them.\r\n     order by cs.requested_start nulls last, s.created_at\r\n  loop\r\n    v_sender := coalesce(v_row.metadata->'sender', v_row.metadata->'senderDetails', '{}'::jsonb);\r\n    v_order := v_order + 1;\r\n\r\n    insert into public.driver_run_stops (\r\n      run_id, shipment_id, stop_order, stop_type, status, address, latitude, longitude,\r\n      recipient_name, time_window_start, time_window_end)\r\n    values (\r\n      v_driver_run_id, v_row.id, v_order, 'collection', 'planned',\r\n      nullif(btrim(concat_ws(', ',\r\n        nullif(v_sender->>'address', ''), nullif(v_sender->>'city', ''),\r\n        nullif(coalesce(v_sender->>'postalCode', v_sender->>'postcode'), ''))), ''),\r\n      v_row.pickup_latitude, v_row.pickup_longitude,\r\n      nullif(btrim(concat_ws(' ', v_sender->>'firstName', v_sender->>'lastName')), ''),\r\n      case when v_row.requested_start is null then null\r\n           else (v_run.collection_date + v_row.requested_start) at time zone 'UTC' end,\r\n      case when v_row.requested_end is null then null\r\n           else (v_run.collection_date + v_row.requested_end) at time zone 'UTC' end);\r\n\r\n    -- Honour the customer's own window as the dispatch window. Identical to\r\n    -- what they asked for, so this raises no \"moved\" flag and owes no call.\r\n    if v_row.requested_at is not null and not v_row.requested_flexible\r\n       and v_row.requested_start is not null then\r\n      update public.collection_slots\r\n         set dispatch_start = v_row.requested_start,\r\n             dispatch_end = v_row.requested_end,\r\n             dispatch_set_at = now(),\r\n             dispatch_set_by = auth.uid()\r\n       where shipment_id = v_row.id;\r\n    end if;\r\n\r\n    v_added := v_added + 1;\r\n  end loop;\r\n\r\n  update public.shipments set assigned_driver_id = p_driver_id\r\n   where collection_run_id = p_run_id and deleted_at is null\r\n     and lower(coalesce(status, '')) in ('booking confirmed', 'confirmed', 'pending');\r\n\r\n  update public.collection_runs\r\n     set driver_run_id = v_driver_run_id, status = 'active'\r\n   where id = p_run_id;\r\n\r\n  return jsonb_build_object(\r\n    'assigned', true, 'driverRunId', v_driver_run_id, 'stopsAdded', v_added,\r\n    'route', v_run.route, 'date', v_run.collection_date);\r\nend $$;\r\n\r\nrevoke all on function public.assign_collection_run_driver(uuid, uuid, text) from public, anon;\r\ngrant execute on function public.assign_collection_run_driver(uuid, uuid, text) to authenticated;\r\n\r\n/**\r\n * The drivers dispatch can put on a collection run.\r\n *\r\n * `stops_that_day` is what stops a dispatcher quietly double-booking someone:\r\n * a driver already carrying twenty stops on the 14th should look busy in the\r\n * picker, not identical to one carrying none. Delivery-only drivers are left\r\n * out — they work the Zimbabwe half.\r\n */\r\ncreate or replace function public.collection_drivers(p_date date default null)\r\nreturns table (\r\n  id uuid, full_name text, email text, driver_type text,\r\n  on_leave boolean, stops_that_day integer, run_route text)\r\nlanguage sql stable security definer set search_path = public as $$\r\n  select\r\n    p.id, p.full_name, p.email, coalesce(p.driver_type, 'both'), coalesce(p.on_leave, false),\r\n    coalesce((select count(*)::int from public.driver_run_stops st\r\n               join public.driver_runs r on r.id = st.run_id\r\n              where r.driver_id = p.id and r.run_date = p_date and r.status <> 'cancelled'), 0),\r\n    (select r.route_name from public.driver_runs r\r\n      where r.driver_id = p.id and r.run_date = p_date and r.status <> 'cancelled' limit 1)\r\n  from public.profiles p\r\n  where public.is_operations_admin()\r\n    and (lower(coalesce(p.role, '')) = 'driver' or p.is_admin = true\r\n         or lower(coalesce(p.role, '')) in ('admin', 'logistics'))\r\n    and coalesce(p.staff_active, true)\r\n    and coalesce(p.driver_type, 'both') <> 'delivery'\r\n  order by coalesce(p.on_leave, false), p.full_name\r\n$$;\r\n\r\nrevoke all on function public.collection_drivers(date) from public, anon;\r\ngrant execute on function public.collection_drivers(date) to authenticated;\r\n\n\n-- Booking confirmation, on the website and in the admin app.\r\n--\r\n-- Two things were inconsistent and this settles both.\r\n--\r\n-- 1. A booking made in the customer app landed as 'Booking Confirmed'; the same\r\n--    booking made on the website landed as 'pending'. The customer saw\r\n--    \"Booking Confirmed!\" on the receipt either way, so the website's own\r\n--    confirmation screen was contradicting the record behind it — and every\r\n--    staff view that groups by status put website bookings somewhere else.\r\n--    create_public_booking now writes the same status the app does.\r\n--\r\n-- 2. Admin can now confirm a shipment on the phone and lock its details\r\n--    (metadata.confirmation stamped, can_modify cleared). Nothing enforced\r\n--    that, so a customer could still edit an address after the confirmation\r\n--    call. update_customer_shipment now refuses, and it no longer writes the\r\n--    literal string 'To be confirmed' into a\r\n--    collection date that has none — the apps show the published route date\r\n--    instead, and a placeholder masquerading as data made that impossible.\r\n--\r\n-- Idempotent: safe to re-run.\r\n\r\ncreate or replace function public.create_public_booking(p jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_shipment public.shipments%rowtype;\r\n  v_payment_id uuid;\r\n  v_receipt_id uuid;\r\n  v_currency text := coalesce(nullif(p->>'currency', ''), 'GBP');\r\n  v_amount numeric := coalesce((p->>'amount')::numeric, 0);\r\n  v_tracking text := coalesce(nullif(p->>'trackingNumber', ''), 'ZSN' || lpad(floor(random() * 100000000)::text, 8, '0'));\r\n  v_receipt_no text := coalesce(nullif(p->>'receiptNumber', ''), 'RCP-' || lpad(floor(random() * 10000000000)::text, 10, '0'));\r\n  v_email text := lower(trim(coalesce(p->'metadata'->'sender'->>'email', '')));\r\nbegin\r\n  if v_amount < 0 then raise exception 'Booking amount cannot be negative'; end if;\r\n  if v_email = '' then raise exception 'A sender email address is required'; end if;\r\n  if v_currency not in ('GBP', 'EUR') then raise exception 'Unsupported currency %', v_currency; end if;\r\n\r\n  insert into public.shipments (\r\n    tracking_number, user_id, origin, destination, status, metadata,\r\n    collection_schedule_id, can_modify, can_cancel\r\n  ) values (\r\n    v_tracking,\r\n    -- A signed-in customer's booking is theirs; a guest booking is claimed\r\n    -- later by claim_guest_bookings() using the sender email above.\r\n    v_uid,\r\n    coalesce(p->>'origin', ''),\r\n    coalesce(p->>'destination', ''),\r\n    -- Same status the customer app's create_customer_booking writes, so a\r\n    -- booking means the same thing whichever door it came through.\r\n    'Booking Confirmed',\r\n    coalesce(p->'metadata', '{}'::jsonb),\r\n    nullif(p->>'collectionScheduleId', '')::uuid,\r\n    true, true\r\n  ) returning * into v_shipment;\r\n\r\n  insert into public.payments (\r\n    user_id, shipment_id, amount, currency, payment_method, payment_status, transaction_id\r\n  ) values (\r\n    v_uid, v_shipment.id, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(nullif(p->>'transactionId', ''), 'TX-' || lpad(floor(random() * 1000000000000)::text, 12, '0'))\r\n  ) returning id into v_payment_id;\r\n\r\n  insert into public.receipts (\r\n    user_id, shipment_id, payment_id, receipt_number, amount, currency, payment_method, status,\r\n    sender_details, recipient_details, shipment_details, payment_info, collection_info, payment_schedule\r\n  ) values (\r\n    v_uid, v_shipment.id, v_payment_id, v_receipt_no, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(p->'metadata'->'sender', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'recipient', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'items', '{}'::jsonb),\r\n    coalesce(p->'paymentInfo', '{}'::jsonb),\r\n    coalesce(p->'collectionInfo', '{}'::jsonb),\r\n    p->'paymentSchedule'\r\n  ) returning id into v_receipt_id;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_shipment.id,\r\n    'trackingNumber', v_shipment.tracking_number,\r\n    'paymentId', v_payment_id,\r\n    'receiptId', v_receipt_id,\r\n    'receiptNumber', v_receipt_no,\r\n    'linkedToAccount', v_uid is not null\r\n  );\r\nend $$;\r\n\r\ngrant execute on function public.create_public_booking(jsonb) to anon, authenticated;\r\n\r\n-- Deliberately no backfill of existing 'pending' website bookings. Every staff\r\n-- view already reads the two as one queue, so rewriting historical rows would\r\n-- change live data for no gain. Ask if you want them brought across.\r\n\r\n-- Customers can correct the contact/address/date details of a booking until a\r\n-- driver has started collection *or* an admin has confirmed it on the phone.\r\n-- Otherwise identical to the version this replaces.\r\ncreate or replace function public.update_customer_shipment(p_shipment_id uuid, p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path=public as $$\r\ndeclare v_ship public.shipments%rowtype; v_meta jsonb; v_schedule public.collection_schedules%rowtype;\r\nbegin\r\n  select * into v_ship from public.shipments where id=p_shipment_id and user_id=auth.uid() for update;\r\n  if not found then raise exception 'Shipment not found'; end if;\r\n  if lower(coalesce(v_ship.collection_status,'')) not in ('','awaiting collection')\r\n     or lower(coalesce(v_ship.driver_status,'')) in ('en_route','arrived','collected','completed') then\r\n    raise exception 'This shipment can no longer be edited because collection has started';\r\n  end if;\r\n  -- Admin has been through the booking with the customer and locked it. Keyed\r\n  -- on the confirmation stamp rather than can_modify, because that column\r\n  -- predates this schema and its default is not ours to assume. The message\r\n  -- names the reason: \"cannot be edited\" with no explanation sends the customer\r\n  -- to WhatsApp asking why.\r\n  if (v_ship.metadata->'confirmation'->>'confirmedAt') is not null then\r\n    raise exception 'This booking has been confirmed with you and is locked. Message us and we will make the change.';\r\n  end if;\r\n  if nullif(p->>'scheduleId','') is not null then\r\n    select * into v_schedule from public.collection_schedules where id=(p->>'scheduleId')::uuid;\r\n    if not found then raise exception 'Collection date not found'; end if;\r\n  end if;\r\n  v_meta := coalesce(v_ship.metadata,'{}'::jsonb);\r\n  v_meta := jsonb_set(v_meta,'{sender}',coalesce(p->'sender',v_meta->'sender'),true);\r\n  v_meta := jsonb_set(v_meta,'{recipient}',coalesce(p->'recipient',v_meta->'recipient'),true);\r\n  v_meta := jsonb_set(v_meta,'{collection}',jsonb_build_object(\r\n    -- No placeholder strings. An unassigned route and an unpublished date are\r\n    -- absent, not the words \"To be assigned\" and \"To be confirmed\" — the apps\r\n    -- now fill that gap with the published date for the route, which a\r\n    -- placeholder posing as data made impossible.\r\n    'route',coalesce(p->>'route',v_meta->'collection'->>'route'),\r\n    'date',coalesce(p->>'collectionDate',v_meta->'collection'->>'date'),\r\n    'scheduleId',nullif(p->>'scheduleId','')),true);\r\n  v_meta := jsonb_set(v_meta,'{pricing,paymentMethod}',to_jsonb(coalesce(p->>'paymentMethod',v_meta->'pricing'->>'paymentMethod','Bank Transfer')),true);\r\n  update public.shipments set\r\n    origin=coalesce(p->>'origin',origin), destination=coalesce(p->>'destination',destination),\r\n    collection_schedule_id=nullif(p->>'scheduleId','')::uuid,\r\n    metadata=v_meta, updated_at=now()\r\n  where id=p_shipment_id returning * into v_ship;\r\n  insert into public.audit_logs(user_id,action,entity_type,entity_id,details)\r\n  values(auth.uid(),'CUSTOMER_EDIT_BOOKING','SHIPMENT',p_shipment_id,p);\r\n  return jsonb_build_object('id',v_ship.id,'updatedAt',v_ship.updated_at);\r\nend $$;\r\ngrant execute on function public.update_customer_shipment(uuid,jsonb) to authenticated;\r\n\n\n-- An approved quote becomes one invoice line per item, not one lump.\r\n--\r\n-- The customer already lists their goods item by item, and an admin already\r\n-- prices each of those items separately in the staff app — `custom_quotes`\r\n-- carries the priced breakdown in `quote_items`. But booking off that quote\r\n-- collapsed the whole thing back into a single line:\r\n--\r\n--   Approved quote: Item 1: 3-seater sofa, Item 2: fridge freezer …   £1,850\r\n--\r\n-- which is what made the invoice and the delivery note hard to work from.\r\n-- Nobody loading a container can tick off one line covering nine things, and a\r\n-- customer querying a price has nothing to point at. The breakdown existed the\r\n-- whole time; this stops throwing it away.\r\n--\r\n-- Wraps rather than rewrites, exactly as the previous three revisions of this\r\n-- routine did — the pricing itself is untouched.\r\n--\r\n-- Idempotent: safe to re-run.\r\n\r\ndo $$ begin\r\n  if to_regprocedure('public.create_customer_booking_v3(jsonb)') is null then\r\n    execute 'alter function public.create_customer_booking(jsonb) rename to create_customer_booking_v3';\r\n  end if;\r\nend $$;\r\n\r\ncreate or replace function public.create_customer_booking(p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_result jsonb;\r\n  v_quote_id uuid := nullif(p->>'quoteId', '')::uuid;\r\n  v_quote public.custom_quotes%rowtype;\r\n  v_shipment_id uuid;\r\n  v_ship public.shipments%rowtype;\r\n  v_invoice jsonb;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_item jsonb;\r\n  v_itemised numeric := 0;\r\n  v_line jsonb;\r\n  v_replaced boolean := false;\r\nbegin\r\n  -- Everything the previous version did stays exactly as it was.\r\n  v_result := public.create_customer_booking_v3(p);\r\n  if v_quote_id is null then return v_result; end if;\r\n\r\n  select * into v_quote from public.custom_quotes where id = v_quote_id;\r\n  if not found or v_quote.quote_items is null or jsonb_array_length(v_quote.quote_items) = 0 then\r\n    return v_result;\r\n  end if;\r\n\r\n  -- Every item must carry its own price, and they must add up to the amount the\r\n  -- customer was quoted and agreed. If they do not, the single line stands:\r\n  -- silently re-pricing a booking to make a breakdown fit would be worse than\r\n  -- having no breakdown.\r\n  for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n    if coalesce((v_item->>'amount')::numeric, 0) <= 0 then return v_result; end if;\r\n    v_itemised := v_itemised + (v_item->>'amount')::numeric;\r\n  end loop;\r\n  if abs(v_itemised - coalesce(v_quote.quoted_amount, -1)) > 0.01 then return v_result; end if;\r\n\r\n  v_shipment_id := (v_result->>'id')::uuid;\r\n  select * into v_ship from public.shipments where id = v_shipment_id for update;\r\n  if not found then return v_result; end if;\r\n\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n\r\n  -- Swap the one \"Approved quote: …\" line for the priced breakdown, leaving\r\n  -- every other line (drums, seals, door delivery) exactly where it was.\r\n  for v_line in select * from jsonb_array_elements(coalesce(v_invoice->'items', '[]'::jsonb)) loop\r\n    if not v_replaced and coalesce(v_line->>'description', '') like 'Approved quote:%' then\r\n      v_replaced := true;\r\n      for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n        v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n          'description', left(coalesce(nullif(trim(v_item->>'description'), ''), 'Quoted item'), 200),\r\n          'quantity', 1,\r\n          'unitPrice', (v_item->>'amount')::numeric));\r\n      end loop;\r\n    else\r\n      v_lines := v_lines || jsonb_build_array(v_line);\r\n    end if;\r\n  end loop;\r\n  if not v_replaced then return v_result; end if;\r\n\r\n  v_invoice := jsonb_set(v_invoice, '{items}', v_lines, true);\r\n\r\n  update public.shipments\r\n     set metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{invoice}', v_invoice, true),\r\n         updated_at = now()\r\n   where id = v_shipment_id;\r\n\r\n  return v_result || jsonb_build_object('invoice', v_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated;\r\n\n\n-- Finance staff may attach a received proof to an existing customer's shipment.\r\n-- Customer uploads remain limited to their own account by the existing policy.\r\n\r\ndrop policy if exists \"Finance records customer payment proofs\" on public.payment_proofs;\r\ncreate policy \"Finance records customer payment proofs\" on public.payment_proofs\r\n  for insert to authenticated\r\n  with check (public.is_finance_staff());\r\n\r\ndrop policy if exists \"Finance uploads customer payment proofs\" on storage.objects;\r\ncreate policy \"Finance uploads customer payment proofs\" on storage.objects\r\n  for insert to authenticated\r\n  with check (bucket_id = 'payment-proofs' and public.is_finance_staff());\r\n\n\n-- A website booking gets the same customer reference as an app booking.\r\n--\r\n-- `create_customer_booking` has always stamped one — MAR09260013, from\r\n-- `next_customer_reference` — and the invoice and delivery note are numbered\r\n-- from it (INV-…, DN-…). `create_public_booking` never set the column at all,\r\n-- so a booking made on the website had no reference: staff screens fell back to\r\n-- a computed stand-in, and its documents had nothing stable to be numbered by.\r\n--\r\n-- Same generator, so the two doors produce references from one sequence and\r\n-- cannot collide.\r\n--\r\n-- Idempotent: safe to re-run. Existing rows are left alone — see the note at\r\n-- the end.\r\n\r\n-- The routine is SECURITY DEFINER, but a guest books as `anon`; granting\r\n-- execute keeps it callable if the search path is ever resolved as the caller.\r\ngrant execute on function public.next_customer_reference(text) to anon, authenticated;\r\n\r\ncreate or replace function public.create_public_booking(p jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_shipment public.shipments%rowtype;\r\n  v_payment_id uuid;\r\n  v_receipt_id uuid;\r\n  v_currency text := coalesce(nullif(p->>'currency', ''), 'GBP');\r\n  v_amount numeric := coalesce((p->>'amount')::numeric, 0);\r\n  v_tracking text := coalesce(nullif(p->>'trackingNumber', ''), 'ZSN' || lpad(floor(random() * 100000000)::text, 8, '0'));\r\n  v_receipt_no text := coalesce(nullif(p->>'receiptNumber', ''), 'RCP-' || lpad(floor(random() * 10000000000)::text, 10, '0'));\r\n  v_email text := lower(trim(coalesce(p->'metadata'->'sender'->>'email', '')));\r\n  v_name text;\r\n  v_reference text;\r\nbegin\r\n  if v_amount < 0 then raise exception 'Booking amount cannot be negative'; end if;\r\n  if v_email = '' then raise exception 'A sender email address is required'; end if;\r\n  if v_currency not in ('GBP', 'EUR') then raise exception 'Unsupported currency %', v_currency; end if;\r\n\r\n  -- Same three-letter prefix the app uses: the sender's own name.\r\n  v_name := trim(coalesce(p->'metadata'->'sender'->>'firstName', '') || ' '\r\n                 || coalesce(p->'metadata'->'sender'->>'lastName', ''));\r\n  if v_name = '' then v_name := coalesce(p->'metadata'->'sender'->>'name', ''); end if;\r\n  v_reference := public.next_customer_reference(v_name);\r\n\r\n  insert into public.shipments (\r\n    tracking_number, customer_reference, user_id, origin, destination, status, metadata,\r\n    collection_schedule_id, can_modify, can_cancel\r\n  ) values (\r\n    v_tracking,\r\n    v_reference,\r\n    -- A signed-in customer's booking is theirs; a guest booking is claimed\r\n    -- later by claim_guest_bookings() using the sender email above.\r\n    v_uid,\r\n    coalesce(p->>'origin', ''),\r\n    coalesce(p->>'destination', ''),\r\n    -- Same status the customer app's create_customer_booking writes, so a\r\n    -- booking means the same thing whichever door it came through.\r\n    'Booking Confirmed',\r\n    -- The reference is echoed into metadata as well, which is where the older\r\n    -- website admin screens read it from.\r\n    coalesce(p->'metadata', '{}'::jsonb) || jsonb_build_object(\r\n      'customerReference', v_reference,\r\n      'invoice', coalesce(p->'metadata'->'invoice', '{}'::jsonb)\r\n                 || jsonb_build_object('invoiceNumber', 'INV-' || v_reference),\r\n      'deliveryNote', jsonb_build_object('status', 'Draft', 'number', 'DN-' || v_reference)\r\n    ),\r\n    nullif(p->>'collectionScheduleId', '')::uuid,\r\n    true, true\r\n  ) returning * into v_shipment;\r\n\r\n  insert into public.payments (\r\n    user_id, shipment_id, amount, currency, payment_method, payment_status, transaction_id\r\n  ) values (\r\n    v_uid, v_shipment.id, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(nullif(p->>'transactionId', ''), 'TX-' || lpad(floor(random() * 1000000000000)::text, 12, '0'))\r\n  ) returning id into v_payment_id;\r\n\r\n  insert into public.receipts (\r\n    user_id, shipment_id, payment_id, receipt_number, amount, currency, payment_method, status,\r\n    sender_details, recipient_details, shipment_details, payment_info, collection_info, payment_schedule\r\n  ) values (\r\n    v_uid, v_shipment.id, v_payment_id, v_receipt_no, v_amount, v_currency,\r\n    coalesce(p->>'paymentMethod', 'standard'), 'pending',\r\n    coalesce(p->'metadata'->'sender', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'recipient', '{}'::jsonb),\r\n    coalesce(p->'metadata'->'items', '{}'::jsonb),\r\n    coalesce(p->'paymentInfo', '{}'::jsonb),\r\n    coalesce(p->'collectionInfo', '{}'::jsonb),\r\n    p->'paymentSchedule'\r\n  ) returning id into v_receipt_id;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_shipment.id,\r\n    'trackingNumber', v_shipment.tracking_number,\r\n    'customerReference', v_reference,\r\n    'paymentId', v_payment_id,\r\n    'receiptId', v_receipt_id,\r\n    'receiptNumber', v_receipt_no,\r\n    'linkedToAccount', v_uid is not null\r\n  );\r\nend $$;\r\n\r\ngrant execute on function public.create_public_booking(jsonb) to anon, authenticated;\r\n\r\n-- Existing website bookings keep whatever they have. Back-filling would mint a\r\n-- fresh reference for shipments customers were already given a tracking number\r\n-- for, and would renumber documents that may already be in someone's inbox.\r\n-- The staff apps compute a stable stand-in for those, so nothing is unlabelled.\r\n\n\n-- Verified addresses, so a driver is never sent to a guess.\r\n--\r\n-- Geocoding cannot reach every booking. Roughly 40% of live shipments carry a\r\n-- postcode, and Irish addresses carry no Eircode at all — \"Irish Bar Church\r\n-- Street Tullow, Cork\" is a real pickup. Those resolve, at best, to a town\r\n-- centroid, which is fine for grouping a day's work on a map and useless for\r\n-- driving to a door.\r\n--\r\n-- So a point has a *precision*, and a human has the last word:\r\n--   exact       — a UK postcode centroid or a street-level match\r\n--   approximate — a town centroid; the driver sees a warning\r\n--   manual      — placed or corrected by admin; always treated as exact\r\n--   failed      — every lookup missed; needs a human to place the pin\r\n--   null        — never geocoded\r\n--\r\n-- Verification is separate from precision: an admin confirming the address is\r\n-- right is a different claim from the geocoder being confident, and the driver\r\n-- app shows a banner until someone has made the first claim. Per the agreed\r\n-- scope an unverified address warns but never blocks — drivers keep working\r\n-- while admin catches up.\r\n\r\nalter table public.shipments\r\n  add column if not exists pickup_address_verified boolean not null default false,\r\n  add column if not exists pickup_address_verified_at timestamptz,\r\n  add column if not exists pickup_address_verified_by uuid references auth.users(id) on delete set null,\r\n  add column if not exists pickup_geocode_precision text,\r\n  add column if not exists delivery_latitude double precision,\r\n  add column if not exists delivery_longitude double precision,\r\n  add column if not exists delivery_address_verified boolean not null default false,\r\n  add column if not exists delivery_address_verified_at timestamptz,\r\n  add column if not exists delivery_address_verified_by uuid references auth.users(id) on delete set null,\r\n  add column if not exists delivery_geocode_precision text;\r\n\r\ndo $$\r\nbegin\r\n  if not exists (\r\n    select 1 from pg_constraint where conname = 'shipments_pickup_geocode_precision_check'\r\n  ) then\r\n    alter table public.shipments add constraint shipments_pickup_geocode_precision_check\r\n      check (pickup_geocode_precision is null\r\n             -- 'failed' is what stops a bulk run looping for ever. A row with\r\n             -- no coordinates is selected by every pass, so an address no\r\n             -- geocoder can place would be retried until the end of time and\r\n             -- the rows behind it never reached. Recording the failure both\r\n             -- ends the loop and tells admin which addresses need a pin.\r\n             or pickup_geocode_precision in ('exact', 'approximate', 'manual', 'failed'));\r\n  end if;\r\n  if not exists (\r\n    select 1 from pg_constraint where conname = 'shipments_delivery_geocode_precision_check'\r\n  ) then\r\n    alter table public.shipments add constraint shipments_delivery_geocode_precision_check\r\n      check (delivery_geocode_precision is null\r\n             or delivery_geocode_precision in ('exact', 'approximate', 'manual'));\r\n  end if;\r\nend $$;\r\n\r\n-- The driver's route query asks \"today's collections that have a point\"; the\r\n-- admin's cleanup queue asks the opposite. One partial index serves both.\r\ncreate index if not exists shipments_pickup_point_idx\r\n  on public.shipments (pickup_latitude, pickup_longitude)\r\n  where deleted_at is null;\r\n\r\ncreate index if not exists shipments_pickup_unverified_idx\r\n  on public.shipments (pickup_address_verified)\r\n  where deleted_at is null and pickup_address_verified = false;\r\n\r\n/**\r\n * Admin confirms an address, and may place the point by hand.\r\n *\r\n * Passing coordinates marks the precision 'manual', which is what makes this\r\n * usable for the addresses no geocoder will ever resolve: someone looks the\r\n * place up, drops the pin, and the driver can navigate to it like any other.\r\n * Passing no coordinates just records the human check against whatever the\r\n * geocoder found.\r\n */\r\ncreate or replace function public.set_shipment_address_verification(\r\n  p_shipment_id uuid,\r\n  p_which text,\r\n  p_verified boolean default true,\r\n  p_latitude double precision default null,\r\n  p_longitude double precision default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_which text := lower(coalesce(p_which, 'pickup'));\r\n  v_has_point boolean := p_latitude is not null and p_longitude is not null;\r\n  v_row public.shipments%rowtype;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Only admin or finance can verify an address'\r\n      using errcode = '42501';\r\n  end if;\r\n\r\n  if v_which not in ('pickup', 'delivery') then\r\n    raise exception 'p_which must be pickup or delivery, got %', p_which\r\n      using errcode = '22023';\r\n  end if;\r\n\r\n  -- Guard the point before it is written: a swapped lat/lng, or a zero pair\r\n  -- from an empty form, would put a driver in the Atlantic.\r\n  if v_has_point and (p_latitude < -90 or p_latitude > 90 or p_longitude < -180 or p_longitude > 180) then\r\n    raise exception 'Coordinates out of range: %, %', p_latitude, p_longitude\r\n      using errcode = '22023';\r\n  end if;\r\n  if v_has_point and p_latitude = 0 and p_longitude = 0 then\r\n    raise exception 'Refusing to save a null island coordinate'\r\n      using errcode = '22023';\r\n  end if;\r\n\r\n  if v_which = 'pickup' then\r\n    update public.shipments set\r\n      pickup_address_verified = coalesce(p_verified, true),\r\n      pickup_address_verified_at = case when coalesce(p_verified, true) then now() else null end,\r\n      pickup_address_verified_by = case when coalesce(p_verified, true) then auth.uid() else null end,\r\n      pickup_latitude = case when v_has_point then p_latitude else pickup_latitude end,\r\n      pickup_longitude = case when v_has_point then p_longitude else pickup_longitude end,\r\n      pickup_geocode_precision = case when v_has_point then 'manual' else pickup_geocode_precision end,\r\n      updated_at = now()\r\n    where id = p_shipment_id\r\n    returning * into v_row;\r\n  else\r\n    update public.shipments set\r\n      delivery_address_verified = coalesce(p_verified, true),\r\n      delivery_address_verified_at = case when coalesce(p_verified, true) then now() else null end,\r\n      delivery_address_verified_by = case when coalesce(p_verified, true) then auth.uid() else null end,\r\n      delivery_latitude = case when v_has_point then p_latitude else delivery_latitude end,\r\n      delivery_longitude = case when v_has_point then p_longitude else delivery_longitude end,\r\n      delivery_geocode_precision = case when v_has_point then 'manual' else delivery_geocode_precision end,\r\n      updated_at = now()\r\n    where id = p_shipment_id\r\n    returning * into v_row;\r\n  end if;\r\n\r\n  if v_row.id is null then\r\n    raise exception 'Shipment % not found', p_shipment_id using errcode = 'P0002';\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'id', v_row.id,\r\n    'which', v_which,\r\n    'verified', case when v_which = 'pickup' then v_row.pickup_address_verified else v_row.delivery_address_verified end,\r\n    'latitude', case when v_which = 'pickup' then v_row.pickup_latitude else v_row.delivery_latitude end,\r\n    'longitude', case when v_which = 'pickup' then v_row.pickup_longitude else v_row.delivery_longitude end,\r\n    'precision', case when v_which = 'pickup' then v_row.pickup_geocode_precision else v_row.delivery_geocode_precision end\r\n  );\r\nend $$;\r\n\r\nrevoke all on function public.set_shipment_address_verification(uuid, text, boolean, double precision, double precision) from public, anon;\r\ngrant execute on function public.set_shipment_address_verification(uuid, text, boolean, double precision, double precision) to authenticated;\r\n\r\n/**\r\n * Editing an address invalidates the verification that was made against the\r\n * old one.\r\n *\r\n * Without this a verified pin survives an address change and the driver is\r\n * confidently routed to the previous house. The point is cleared too, so the\r\n * geocoder picks the row up again on its next pass.\r\n */\r\ncreate or replace function public.reset_address_verification_on_change()\r\nreturns trigger\r\nlanguage plpgsql\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  old_pickup text := lower(trim(coalesce(\r\n    old.metadata->'sender'->>'address', old.metadata->'senderDetails'->>'address', '')));\r\n  new_pickup text := lower(trim(coalesce(\r\n    new.metadata->'sender'->>'address', new.metadata->'senderDetails'->>'address', '')));\r\n  old_drop text := lower(trim(coalesce(\r\n    old.metadata->'recipient'->>'address', old.metadata->'recipientDetails'->>'address', '')));\r\n  new_drop text := lower(trim(coalesce(\r\n    new.metadata->'recipient'->>'address', new.metadata->'recipientDetails'->>'address', '')));\r\nbegin\r\n  if new_pickup is distinct from old_pickup then\r\n    new.pickup_address_verified := false;\r\n    new.pickup_address_verified_at := null;\r\n    new.pickup_address_verified_by := null;\r\n    new.pickup_latitude := null;\r\n    new.pickup_longitude := null;\r\n    new.pickup_geocode_precision := null;\r\n  end if;\r\n\r\n  if new_drop is distinct from old_drop then\r\n    new.delivery_address_verified := false;\r\n    new.delivery_address_verified_at := null;\r\n    new.delivery_address_verified_by := null;\r\n    new.delivery_latitude := null;\r\n    new.delivery_longitude := null;\r\n    new.delivery_geocode_precision := null;\r\n  end if;\r\n\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists shipments_reset_address_verification on public.shipments;\r\ncreate trigger shipments_reset_address_verification\r\n  before update of metadata on public.shipments\r\n  for each row\r\n  execute function public.reset_address_verification_on_change();\r\n\n\n-- Drivers start their own routes.\r\n--\r\n-- The run/stop engine already does everything a collection day needs — status\r\n-- transitions, arrivals, scanning, seals, offline replay — but nothing has\r\n-- created a run since the dispatcher board was retired, so all of it has sat\r\n-- idle with zero rows. These two routines give the driver the one thing\r\n-- dispatch used to provide: a run to work through.\r\n--\r\n-- `driver_runs` is unique on (driver_id, run_date), so a run is *the driver's\r\n-- day*, not a single route. Starting a second route appends its collections to\r\n-- the same run, which is what happens in practice when a short route finishes\r\n-- early and the driver picks up another.\r\n\r\n/**\r\n * Start (or resume) today's run and add a route's collections to it.\r\n *\r\n * Shipments arrive in the order the driver should drive them — the optimiser\r\n * has already run on the phone — and are appended after whatever is already on\r\n * the run. Re-starting a route the driver is already working is a no-op for\r\n * the stops that exist, so tapping it twice cannot duplicate a collection.\r\n */\r\ncreate or replace function public.start_collection_route(\r\n  p_route_name text,\r\n  p_shipment_ids uuid[],\r\n  p_date date default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_driver uuid := auth.uid();\r\n  v_date date := coalesce(p_date, current_date);\r\n  v_run_id uuid;\r\n  v_next integer;\r\n  v_added integer := 0;\r\n  v_shipment uuid;\r\nbegin\r\n  if v_driver is null then\r\n    raise exception 'Sign in required' using errcode = '42501';\r\n  end if;\r\n\r\n  -- A driver may only start their own run. Admins get in for support.\r\n  if not (public.is_staff_member() or public.is_operations_admin()) then\r\n    raise exception 'Staff access required' using errcode = '42501';\r\n  end if;\r\n\r\n  insert into public.driver_runs as r (driver_id, run_date, status, route_name, run_type, started_at)\r\n  values (v_driver, v_date, 'active', nullif(trim(coalesce(p_route_name, '')), ''), 'pickup', now())\r\n  on conflict (driver_id, run_date) do update\r\n    set status = case when r.status in ('completed', 'cancelled') then r.status else 'active' end,\r\n        -- Keep the first route's name when a second is appended, rather than\r\n        -- silently relabelling the day.\r\n        route_name = coalesce(r.route_name, excluded.route_name),\r\n        started_at = coalesce(r.started_at, now()),\r\n        updated_at = now()\r\n  returning r.id into v_run_id;\r\n\r\n  select coalesce(max(stop_order), 0) + 1 into v_next\r\n  from public.driver_run_stops where run_id = v_run_id;\r\n\r\n  -- foreach preserves the caller's order, which is the optimised order.\r\n  foreach v_shipment in array coalesce(p_shipment_ids, array[]::uuid[])\r\n  loop\r\n    -- Already on this run? Leave it exactly as it is; it may be half worked.\r\n    if exists (\r\n      select 1 from public.driver_run_stops\r\n      where run_id = v_run_id and shipment_id = v_shipment\r\n    ) then\r\n      continue;\r\n    end if;\r\n\r\n    insert into public.driver_run_stops (\r\n      run_id, shipment_id, stop_order, stop_type, status, address, latitude, longitude\r\n    )\r\n    select\r\n      v_run_id,\r\n      s.id,\r\n      v_next,\r\n      'collection',\r\n      'planned',\r\n      coalesce(\r\n        s.metadata->'sender'->>'address',\r\n        s.metadata->'senderDetails'->>'address'\r\n      ),\r\n      s.pickup_latitude,\r\n      s.pickup_longitude\r\n    from public.shipments s\r\n    where s.id = v_shipment and s.deleted_at is null;\r\n\r\n    if found then\r\n      v_next := v_next + 1;\r\n      v_added := v_added + 1;\r\n    end if;\r\n  end loop;\r\n\r\n  return jsonb_build_object(\r\n    'runId', v_run_id,\r\n    'date', v_date,\r\n    'added', v_added,\r\n    'stops', (\r\n      select coalesce(jsonb_agg(jsonb_build_object(\r\n        'stopId', st.id,\r\n        'shipmentId', st.shipment_id,\r\n        'stopOrder', st.stop_order,\r\n        'status', st.status\r\n      ) order by st.stop_order), '[]'::jsonb)\r\n      from public.driver_run_stops st where st.run_id = v_run_id\r\n    )\r\n  );\r\nend $$;\r\n\r\nrevoke all on function public.start_collection_route(text, uuid[], date) from public, anon;\r\ngrant execute on function public.start_collection_route(text, uuid[], date) to authenticated;\r\n\r\n/**\r\n * Reorder the stops a driver has not finished yet.\r\n *\r\n * Only outstanding work moves. Completed and failed stops keep the positions\r\n * they were actually worked in, because the run doubles as the record of what\r\n * happened and rewriting history would make the day's audit trail a fiction.\r\n * The reordered stops are numbered after them.\r\n */\r\ncreate or replace function public.reorder_driver_stops(\r\n  p_run_id uuid,\r\n  p_stop_ids uuid[]\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_driver uuid;\r\n  v_done integer;\r\n  v_index integer := 0;\r\n  v_stop uuid;\r\n  v_moved integer := 0;\r\nbegin\r\n  select driver_id into v_driver from public.driver_runs where id = p_run_id;\r\n  if v_driver is null then\r\n    raise exception 'Run % not found', p_run_id using errcode = 'P0002';\r\n  end if;\r\n  if v_driver <> auth.uid() and not public.is_operations_admin() then\r\n    raise exception 'That is not your run' using errcode = '42501';\r\n  end if;\r\n\r\n  select count(*) into v_done\r\n  from public.driver_run_stops\r\n  where run_id = p_run_id and status in ('completed', 'failed');\r\n\r\n  -- Two passes, because stop_order has no unique constraint but sharing a\r\n  -- number would still make the driver's list order arbitrary. Park the moving\r\n  -- stops well clear of the finished ones first.\r\n  update public.driver_run_stops\r\n     set stop_order = stop_order + 100000\r\n   where run_id = p_run_id and status not in ('completed', 'failed');\r\n\r\n  foreach v_stop in array coalesce(p_stop_ids, array[]::uuid[])\r\n  loop\r\n    v_index := v_index + 1;\r\n    update public.driver_run_stops\r\n       set stop_order = v_done + v_index, updated_at = now()\r\n     where id = v_stop\r\n       and run_id = p_run_id\r\n       and status not in ('completed', 'failed');\r\n    if found then v_moved := v_moved + 1; end if;\r\n  end loop;\r\n\r\n  -- Anything the caller did not mention (a stop added on another device, say)\r\n  -- keeps a stable position at the end rather than colliding on a number.\r\n  with stragglers as (\r\n    select id, row_number() over (order by stop_order) as rn\r\n    from public.driver_run_stops\r\n    where run_id = p_run_id and stop_order > 100000\r\n  )\r\n  update public.driver_run_stops st\r\n     set stop_order = v_done + v_index + s.rn\r\n    from stragglers s\r\n   where st.id = s.id;\r\n\r\n  -- Finished stops are renumbered 1..n in the order they were worked, so the\r\n  -- list reads chronologically from the top.\r\n  with worked as (\r\n    select id, row_number() over (\r\n      order by coalesce(completed_at, failed_at, arrived_at, created_at)\r\n    ) as rn\r\n    from public.driver_run_stops\r\n    where run_id = p_run_id and status in ('completed', 'failed')\r\n  )\r\n  update public.driver_run_stops st\r\n     set stop_order = w.rn\r\n    from worked w\r\n   where st.id = w.id;\r\n\r\n  return jsonb_build_object('runId', p_run_id, 'moved', v_moved, 'completed', v_done);\r\nend $$;\r\n\r\nrevoke all on function public.reorder_driver_stops(uuid, uuid[]) from public, anon;\r\ngrant execute on function public.reorder_driver_stops(uuid, uuid[]) to authenticated;\r\n\r\n/**\r\n * A driver's own run for a date, with its stops joined to what the driver\r\n * needs at the door.\r\n *\r\n * One read, so the route screen does not fan out into a query per stop.\r\n */\r\ncreate or replace function public.driver_run_for_date(p_date date default null)\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select coalesce(\r\n    (select jsonb_build_object(\r\n       'runId', r.id,\r\n       'routeName', r.route_name,\r\n       'status', r.status,\r\n       'date', r.run_date,\r\n       'startedAt', r.started_at,\r\n       'stops', coalesce((\r\n         select jsonb_agg(jsonb_build_object(\r\n           'stopId', st.id,\r\n           'shipmentId', st.shipment_id,\r\n           'stopOrder', st.stop_order,\r\n           'status', st.status,\r\n           'address', st.address,\r\n           'latitude', st.latitude,\r\n           'longitude', st.longitude,\r\n           'arrivedAt', st.arrived_at,\r\n           'completedAt', st.completed_at,\r\n           'customerReference', s.customer_reference,\r\n           'trackingNumber', s.tracking_number,\r\n           'customerName', coalesce(\r\n             s.metadata->'sender'->>'name',\r\n             trim(concat_ws(' ',\r\n               s.metadata->'sender'->>'firstName',\r\n               s.metadata->'sender'->>'lastName'))),\r\n           'phone', s.metadata->'sender'->>'phone',\r\n           'addressVerified', s.pickup_address_verified,\r\n           'geocodePrecision', s.pickup_geocode_precision\r\n         ) order by st.stop_order)\r\n         from public.driver_run_stops st\r\n         join public.shipments s on s.id = st.shipment_id\r\n         where st.run_id = r.id\r\n       ), '[]'::jsonb)\r\n     )\r\n     from public.driver_runs r\r\n     where r.driver_id = auth.uid()\r\n       and r.run_date = coalesce(p_date, current_date)\r\n     limit 1),\r\n    'null'::jsonb\r\n  );\r\n$$;\r\n\r\nrevoke all on function public.driver_run_for_date(date) from public, anon;\r\ngrant execute on function public.driver_run_for_date(date) to authenticated;\r\n\n\n-- The collection itself: identity at the door, the invoice, and the lock.\r\n--\r\n-- Three rules from the agreed flow that the existing routines got wrong:\r\n--\r\n--   1. Identity is QR *or* PIN, never both. complete_driver_handover demanded a\r\n--      scanned QR **and** a matching six-digit code, so a customer whose phone\r\n--      was flat could not be collected from at all. Scanning proves the driver\r\n--      is at the right shipment; the code proves it when there is nothing to\r\n--      scan. Either is enough, neither alone is optional.\r\n--\r\n--   2. Photos are optional. The routine refused to complete a collection\r\n--      without a 'pickup_departure' photo, which is a hard block on a driver\r\n--      whose camera or storage fails, for evidence that is nice to have rather\r\n--      than required.\r\n--\r\n--   3. Drivers may correct the whole invoice, not just the wording. The old\r\n--      routine locked quantity and price (\"Drivers may correct the wording\r\n--      only\"), which leaves the invoice wrong whenever the goods at the door\r\n--      differ from the booking - the exact case the driver is there to catch.\r\n--      They may now change descriptions, quantities, prices, add and remove\r\n--      lines, and record what was actually paid.\r\n--\r\n-- What replaces the old locks is a real one: once the driver confirms, the\r\n-- invoice is closed to them for good. Admin and finance can still edit it.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Every booking starts with a draft invoice and a draft delivery note\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * A booking is not just a shipment: it is an invoice waiting to be confirmed\r\n * and a delivery note waiting to be filled in. Creating both up front is what\r\n * lets the website, the staff app and the customer all show the same paperwork\r\n * from the moment the booking is confirmed.\r\n *\r\n * Deliberately a trigger rather than an edit to each booking routine: bookings\r\n * arrive from the website, the customer app and manual admin entry, and only a\r\n * trigger catches all three (and anything added later).\r\n *\r\n * A quote that already priced the job keeps its invoice untouched. No due date\r\n * is invented — an invented one would make the invoice read \"overdue\" on a day\r\n * nobody chose.\r\n */\r\ncreate or replace function public.ensure_booking_paperwork()\r\nreturns trigger\r\nlanguage plpgsql\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_invoice jsonb := new.metadata->'invoice';\r\n  v_currency text;\r\n  v_amount numeric;\r\nbegin\r\n  if v_invoice is null or jsonb_typeof(v_invoice) <> 'object' then\r\n    -- Ireland prices in euro, everywhere else in pounds. `origin` carries\r\n    -- trailing spaces on live rows, hence the trim.\r\n    v_currency := case\r\n      when lower(trim(coalesce(new.origin, ''))) in ('ireland', 'republic of ireland', 'eire')\r\n        then 'EUR' else 'GBP' end;\r\n\r\n    v_amount := coalesce(\r\n      (new.metadata->'pricing'->>'finalAmount')::numeric,\r\n      (new.metadata->'pricing'->>'total')::numeric,\r\n      (new.metadata->>'quotedAmount')::numeric,\r\n      0);\r\n\r\n    new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(\r\n      'invoice', jsonb_build_object(\r\n        'invoiceNumber', 'INV-' || to_char(now(), 'YYYYMMDD') || '-' ||\r\n                         upper(substr(replace(new.id::text, '-', ''), 1, 6)),\r\n        'issueDate', to_char(now(), 'YYYY-MM-DD'),\r\n        'currency', v_currency,\r\n        'items', case when v_amount > 0 then jsonb_build_array(jsonb_build_object(\r\n                        'description', 'Shipping and collection service',\r\n                        'quantity', 1,\r\n                        'unitPrice', v_amount))\r\n                 else '[]'::jsonb end,\r\n        'discount', 0,\r\n        'taxRate', 0,\r\n        'payments', '[]'::jsonb,\r\n        'createdAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF')\r\n      ));\r\n  end if;\r\n\r\n  if new.delivery_note_status is null then\r\n    new.delivery_note_status := 'Draft';\r\n  end if;\r\n\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists shipments_ensure_booking_paperwork on public.shipments;\r\ncreate trigger shipments_ensure_booking_paperwork\r\n  before insert on public.shipments\r\n  for each row\r\n  execute function public.ensure_booking_paperwork();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A2. Opening the shipment with the code instead of the scan\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- The QR scan already had somewhere to record itself; the code did not, so the\r\n-- app could only ever unlock a stop by scanning. This is the code's equivalent.\r\nalter table public.driver_run_stops\r\n  add column if not exists code_verified_at timestamptz;\r\n\r\n/**\r\n * Open the shipment by the six-digit code from the customer's app.\r\n *\r\n * The counterpart to verify_driver_stop_qr, for the customer whose phone is\r\n * flat, who cannot find the QR, or who reads the code out over the phone\r\n * because they had to leave a neighbour with the parcels.\r\n */\r\ncreate or replace function public.verify_driver_stop_code(\r\n  p_stop_id uuid,\r\n  p_code text\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_stop public.driver_run_stops%rowtype;\r\n  v_run public.driver_runs%rowtype;\r\n  v_ship public.shipments%rowtype;\r\n  v_expected text;\r\n  v_code text := trim(coalesce(p_code, ''));\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if v_run.driver_id <> auth.uid() and not public.is_operations_admin() then\r\n    raise exception 'Stop is not assigned to you' using errcode = '42501';\r\n  end if;\r\n\r\n  select * into v_ship from public.shipments where id = v_stop.shipment_id;\r\n  v_expected := case when v_stop.stop_type = 'collection'\r\n                     then v_ship.collection_code else v_ship.delivery_code end;\r\n\r\n  if v_expected is null then\r\n    raise exception 'This shipment has no handover code. Scan the customer QR code instead.';\r\n  end if;\r\n  if v_code <> v_expected then\r\n    raise exception 'That code does not match this shipment';\r\n  end if;\r\n\r\n  update public.driver_run_stops\r\n     set code_verified_at = now(), updated_at = now()\r\n   where id = v_stop.id;\r\n\r\n  return jsonb_build_object('stopId', v_stop.id, 'verified', true, 'method', 'code');\r\nend $$;\r\n\r\ngrant execute on function public.verify_driver_stop_code(uuid, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. The driver's invoice\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Save, and optionally confirm, the invoice for a collection.\r\n *\r\n * `p_confirm` is the point of no return for the driver: it stamps\r\n * driverConfirmedAt, and every later call from a driver is refused. Admin and\r\n * finance keep full access, because a confirmed invoice still has to be\r\n * correctable when a customer disputes it.\r\n *\r\n * Money taken at the door is appended to metadata.invoice.payments, which is\r\n * where every other surface already reads it from — so paid / partially paid\r\n * follows automatically on the customer's app, the admin dashboard, finance\r\n * and the website, with no second source of truth to keep in step.\r\n */\r\ncreate or replace function public.create_driver_invoice(\r\n  p_stop_id uuid,\r\n  p_line_items jsonb,\r\n  p_discount numeric default 0,\r\n  p_tax_rate numeric default 0,\r\n  p_currency text default 'GBP',\r\n  p_notes text default null,\r\n  p_amount_paid numeric default null,\r\n  p_payment_method text default null,\r\n  p_confirm boolean default false\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_stop public.driver_run_stops%rowtype;\r\n  v_run public.driver_runs%rowtype;\r\n  v_ship public.shipments%rowtype;\r\n  v_invoice public.driver_invoices%rowtype;\r\n  v_meta_invoice jsonb;\r\n  v_items jsonb;\r\n  v_payments jsonb;\r\n  v_discount numeric;\r\n  v_tax_rate numeric;\r\n  v_currency text;\r\n  v_subtotal numeric := 0;\r\n  v_tax numeric := 0;\r\n  v_total numeric := 0;\r\n  v_number text;\r\n  v_is_staff boolean := public.is_operations_admin() or public.is_finance_staff();\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if not v_is_staff and (v_run.driver_id <> auth.uid() or v_stop.stop_type <> 'collection') then\r\n    raise exception 'Pickup driver access required';\r\n  end if;\r\n  if v_stop.status <> 'arrived' and not v_is_staff then\r\n    raise exception 'Mark the collection as arrived first';\r\n  end if;\r\n\r\n  select * into v_ship from public.shipments where id = v_stop.shipment_id for update;\r\n  v_meta_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n\r\n  -- The lock. Confirmed is confirmed.\r\n  if not v_is_staff and nullif(v_meta_invoice->>'driverConfirmedAt', '') is not null then\r\n    raise exception 'This invoice was confirmed and can no longer be changed. Ask admin or finance to amend it.'\r\n      using errcode = '42501';\r\n  end if;\r\n\r\n  if jsonb_typeof(p_line_items) <> 'array' or jsonb_array_length(p_line_items) = 0 then\r\n    raise exception 'Add at least one invoice item';\r\n  end if;\r\n\r\n  -- Normalise every line, so a missing quantity cannot silently zero a price.\r\n  select coalesce(jsonb_agg(jsonb_build_object(\r\n           'description', coalesce(nullif(trim(x->>'description'), ''), 'Item'),\r\n           'quantity', greatest(0, coalesce((x->>'quantity')::numeric, 1)),\r\n           'unitPrice', greatest(0, coalesce((x->>'unitPrice')::numeric, 0)))), '[]'::jsonb)\r\n    into v_items\r\n    from jsonb_array_elements(p_line_items) x;\r\n\r\n  v_discount := greatest(0, coalesce(p_discount, 0));\r\n  v_tax_rate := greatest(0, coalesce(p_tax_rate, 0));\r\n  v_currency := upper(coalesce(nullif(trim(p_currency), ''), v_meta_invoice->>'currency', 'GBP'));\r\n\r\n  select coalesce(sum(coalesce((x->>'quantity')::numeric, 0) * coalesce((x->>'unitPrice')::numeric, 0)), 0)\r\n    into v_subtotal from jsonb_array_elements(v_items) x;\r\n  v_tax := greatest(0, v_subtotal - v_discount) * v_tax_rate / 100;\r\n  v_total := greatest(0, v_subtotal - v_discount) + v_tax;\r\n\r\n  v_number := coalesce(nullif(v_meta_invoice->>'invoiceNumber', ''),\r\n                       'INV-' || to_char(now(), 'YYYYMMDD') || '-' ||\r\n                       upper(substr(replace(v_stop.id::text, '-', ''), 1, 6)));\r\n\r\n  -- Money taken at the door, appended rather than replaced: a part payment now\r\n  -- and another later are two entries, and the running total is their sum.\r\n  v_payments := coalesce(v_meta_invoice->'payments', '[]'::jsonb);\r\n  if coalesce(p_amount_paid, 0) > 0 then\r\n    v_payments := v_payments || jsonb_build_array(jsonb_build_object(\r\n      'amount', p_amount_paid,\r\n      'method', coalesce(nullif(trim(p_payment_method), ''), 'Cash on collection'),\r\n      'date', to_char(now(), 'YYYY-MM-DD'),\r\n      'recordedBy', 'driver'));\r\n  end if;\r\n\r\n  insert into public.driver_invoices(\r\n    shipment_id, stop_id, driver_id, invoice_number, currency,\r\n    line_items, subtotal, discount, tax, total, notes)\r\n  values (v_stop.shipment_id, v_stop.id, coalesce(v_run.driver_id, auth.uid()), v_number, v_currency,\r\n          v_items, v_subtotal, v_discount, v_tax, v_total, p_notes)\r\n  on conflict (stop_id) do update set\r\n    line_items = excluded.line_items, subtotal = excluded.subtotal,\r\n    discount = excluded.discount, tax = excluded.tax, total = excluded.total,\r\n    currency = excluded.currency, notes = excluded.notes, updated_at = now()\r\n  returning * into v_invoice;\r\n\r\n  v_meta_invoice := v_meta_invoice || jsonb_build_object(\r\n    'invoiceNumber', v_invoice.invoice_number,\r\n    'issueDate', coalesce(v_meta_invoice->>'issueDate', to_char(now(), 'YYYY-MM-DD')),\r\n    'items', v_items,\r\n    'discount', v_discount,\r\n    'taxRate', v_tax_rate,\r\n    'currency', v_currency,\r\n    'payments', v_payments,\r\n    'notes', coalesce(p_notes, v_meta_invoice->>'notes'));\r\n\r\n  if p_confirm then\r\n    v_meta_invoice := v_meta_invoice || jsonb_build_object(\r\n      'driverConfirmedAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF'),\r\n      'driverConfirmedBy', auth.uid(),\r\n      -- sentAt is what moves it out of \"draft\" for every reader.\r\n      'sentAt', coalesce(v_meta_invoice->>'sentAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF')));\r\n  end if;\r\n\r\n  update public.shipments\r\n     set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('invoice', v_meta_invoice),\r\n         updated_at = now()\r\n   where id = v_stop.shipment_id;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when p_confirm then 'DRIVER_INVOICE_CONFIRM' else 'DRIVER_INVOICE_SAVE' end,\r\n          'DRIVER_INVOICE', v_invoice.id,\r\n          jsonb_build_object('stopId', v_stop.id, 'total', v_total,\r\n                             'paid', coalesce(p_amount_paid, 0), 'confirmed', p_confirm));\r\n\r\n  return to_jsonb(v_invoice) || jsonb_build_object('confirmed', p_confirm, 'invoice', v_meta_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_driver_invoice(uuid, jsonb, numeric, numeric, text, text, numeric, text, boolean) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Completing the stop\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.complete_driver_handover(\r\n  p_stop_id uuid,\r\n  p_customer_code text default null,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_stop public.driver_run_stops%rowtype;\r\n  v_run public.driver_runs%rowtype;\r\n  v_ship public.shipments%rowtype;\r\n  v_now timestamptz := now();\r\n  v_proofs int := 0;\r\n  v_note text;\r\n  v_code text := trim(coalesce(p_customer_code, ''));\r\n  v_scanned boolean;\r\n  v_expected text;\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if v_run.driver_id <> auth.uid() then raise exception 'Stop is not assigned to you'; end if;\r\n  if v_stop.status <> 'arrived' then raise exception 'Mark the stop as arrived first'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = v_stop.shipment_id for update;\r\n  select count(*) into v_proofs from public.driver_proofs where stop_id = v_stop.id;\r\n\r\n  -- Identity: the scan or the code, whichever the customer could manage.\r\n  -- A code already checked when the shipment was opened counts, so the driver\r\n  -- is not asked for the same six digits twice.\r\n  v_scanned := v_stop.qr_verified_at is not null or v_stop.code_verified_at is not null;\r\n  v_expected := case when v_stop.stop_type = 'collection'\r\n                     then v_ship.collection_code else v_ship.delivery_code end;\r\n\r\n  if not v_scanned then\r\n    if v_code = '' then\r\n      raise exception 'Scan the customer QR code, or enter the six-digit code from their app';\r\n    end if;\r\n    if v_expected is null or v_code <> v_expected then\r\n      raise exception 'That code does not match this shipment';\r\n    end if;\r\n  end if;\r\n\r\n  if v_stop.stop_type = 'collection' then\r\n    -- The invoice must be confirmed, not merely drafted: confirming it is the\r\n    -- driver agreeing what was collected and what was paid.\r\n    if nullif(v_ship.metadata->'invoice'->>'driverConfirmedAt', '') is null then\r\n      raise exception 'Confirm the invoice before completing the collection';\r\n    end if;\r\n    update public.shipments\r\n       set status = 'Collected', driver_status = 'collected',\r\n           collected_at = v_now, collected_by = auth.uid(), updated_at = v_now\r\n     where id = v_ship.id;\r\n  else\r\n    v_note := 'DN-' || to_char(now(), 'YYYYMMDD') || '-' ||\r\n              upper(substr(replace(v_stop.id::text, '-', ''), 1, 6));\r\n    insert into public.delivery_notes(\r\n      shipment_id, stop_id, driver_id, note_number, delivery_address,\r\n      delivered_at, customer_code_verified, proof_count, notes, status)\r\n    values (v_ship.id, v_stop.id, auth.uid(), v_note, v_stop.address,\r\n            v_now, true, v_proofs, p_notes, 'completed')\r\n    on conflict (stop_id) do update set\r\n      delivered_at = v_now, customer_code_verified = true, proof_count = v_proofs,\r\n      notes = p_notes, status = 'completed', updated_at = v_now;\r\n    update public.shipments\r\n       set status = 'Delivered', driver_status = 'delivered',\r\n           delivery_note_status = 'Completed', updated_at = v_now\r\n     where id = v_ship.id;\r\n  end if;\r\n\r\n  update public.driver_run_stops\r\n     set status = 'completed', completed_at = v_now, updated_at = v_now\r\n   where id = v_stop.id;\r\n\r\n  if not exists (\r\n    select 1 from public.driver_run_stops\r\n    where run_id = v_run.id and status not in ('completed', 'failed')\r\n  ) then\r\n    update public.driver_runs set status = 'completed', completed_at = v_now, updated_at = v_now\r\n     where id = v_run.id;\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_ship.id,\r\n    'status', case when v_stop.stop_type = 'collection' then 'Collected' else 'Delivered' end,\r\n    'verifiedBy', case when v_scanned then 'qr' else 'code' end,\r\n    'proofCount', v_proofs,\r\n    'deliveryNote', v_note);\r\nend $$;\r\n\r\ngrant execute on function public.complete_driver_handover(uuid, text, text) to authenticated;\r\n\n\n-- The two automatic status moves nobody should have to remember.\r\n--\r\n--   Collected            -> At Warehouse          at 23:59, London time\r\n--   At Warehouse         -> Enroute to Zimbabwe   5 days after the period's\r\n--                                                 last scheduled collection\r\n--\r\n-- Both are written to be safe to run repeatedly and safe to run late: they\r\n-- describe the state the world should be in, and moving nothing is a normal\r\n-- result. That is what makes overnight collections a non-issue - a stop\r\n-- finished at 01:00 simply gets swept the following night, with no special\r\n-- case for a day that ran over.\r\n\r\n/**\r\n * Everything collected today is at the warehouse by the end of the day.\r\n *\r\n * Scheduled hourly and gated on the London hour rather than scheduled once at\r\n * a fixed UTC time, because the United Kingdom changes clocks twice a year and\r\n * a fixed UTC job would silently drift an hour every spring - marking goods in\r\n * at 22:59 through the summer, before the last van is back.\r\n */\r\ncreate or replace function public.sweep_collected_to_warehouse(p_force boolean default false)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_local timestamp := now() at time zone 'Europe/London';\r\n  v_moved integer := 0;\r\nbegin\r\n  -- pg_cron calls this with no JWT, so a null caller is the scheduler. Any\r\n  -- real caller has to be an admin: these routines move every shipment in the\r\n  -- business between states.\r\n  if auth.uid() is not null and not public.is_operations_admin() then\r\n    raise exception 'Admin access required' using errcode = '42501';\r\n  end if;\r\n  if not p_force and extract(hour from v_local) <> 23 then\r\n    return jsonb_build_object('skipped', true, 'reason', 'not 23:00 in London', 'localHour',\r\n                              extract(hour from v_local));\r\n  end if;\r\n\r\n  with moved as (\r\n    update public.shipments\r\n       set status = 'At Warehouse', updated_at = now()\r\n     where status = 'Collected'\r\n       and deleted_at is null\r\n    returning id\r\n  )\r\n  select count(*) into v_moved from moved;\r\n\r\n  if v_moved > 0 then\r\n    insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n    values (null, 'SWEEP_AT_WAREHOUSE', 'SHIPMENT', null,\r\n            jsonb_build_object('moved', v_moved, 'at', now()));\r\n  end if;\r\n\r\n  return jsonb_build_object('moved', v_moved, 'status', 'At Warehouse');\r\nend $$;\r\n\r\n/**\r\n * Goods leave for Zimbabwe five days after the last collection of their period.\r\n *\r\n * \"Last collection of the period\" is the latest *scheduled* date across that\r\n * period's routes (collection_schedules.pickup_on), not the last collection\r\n * actually recorded — a route that slips would otherwise keep pushing the\r\n * departure date back, and the container does not wait.\r\n *\r\n * A shipment's period is taken from the shipment itself where it is set, and\r\n * from its collection schedule where it is not; older bookings only carry the\r\n * schedule.\r\n */\r\ncreate or replace function public.sweep_warehouse_to_enroute(\r\n  p_force boolean default false,\r\n  p_days integer default 5\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_local timestamp := now() at time zone 'Europe/London';\r\n  v_moved integer := 0;\r\nbegin\r\n  -- pg_cron calls this with no JWT, so a null caller is the scheduler. Any\r\n  -- real caller has to be an admin: these routines move every shipment in the\r\n  -- business between states.\r\n  if auth.uid() is not null and not public.is_operations_admin() then\r\n    raise exception 'Admin access required' using errcode = '42501';\r\n  end if;\r\n  -- Once a day is plenty; 06:00 London means the change is there when the\r\n  -- office opens rather than appearing mid-morning.\r\n  if not p_force and extract(hour from v_local) <> 6 then\r\n    return jsonb_build_object('skipped', true, 'reason', 'not 06:00 in London');\r\n  end if;\r\n\r\n  with period_end as (\r\n    select cs.collection_period_id as period_id, max(cs.pickup_on) as last_pickup\r\n      from public.collection_schedules cs\r\n     where cs.collection_period_id is not null\r\n       and cs.pickup_on is not null\r\n     group by cs.collection_period_id\r\n    having max(cs.pickup_on) <= current_date - make_interval(days => greatest(0, p_days))\r\n  ),\r\n  moved as (\r\n    update public.shipments s\r\n       set status = 'Enroute to Zimbabwe', updated_at = now()\r\n      from period_end pe\r\n     where coalesce(\r\n             s.collection_period_id,\r\n             (select cs.collection_period_id from public.collection_schedules cs\r\n               where cs.id = s.collection_schedule_id)\r\n           ) = pe.period_id\r\n       and s.status in ('Collected', 'At Warehouse')\r\n       and s.deleted_at is null\r\n    returning s.id\r\n  )\r\n  select count(*) into v_moved from moved;\r\n\r\n  if v_moved > 0 then\r\n    insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n    values (null, 'SWEEP_ENROUTE', 'SHIPMENT', null,\r\n            jsonb_build_object('moved', v_moved, 'days', p_days, 'at', now()));\r\n  end if;\r\n\r\n  return jsonb_build_object('moved', v_moved, 'status', 'Enroute to Zimbabwe');\r\nend $$;\r\n\r\nrevoke all on function public.sweep_collected_to_warehouse(boolean) from public, anon;\r\nrevoke all on function public.sweep_warehouse_to_enroute(boolean, integer) from public, anon;\r\n-- Admins can run either by hand, for the first backfill and for the month a\r\n-- route slips and somebody needs it moved now.\r\ngrant execute on function public.sweep_collected_to_warehouse(boolean) to authenticated;\r\ngrant execute on function public.sweep_warehouse_to_enroute(boolean, integer) to authenticated;\r\n\r\ndo $$\r\nbegin\r\n  if exists (select 1 from pg_extension where extname = 'pg_cron') then\r\n    perform cron.unschedule(jobid) from cron.job where jobname = 'shipments-at-warehouse';\r\n    perform cron.schedule('shipments-at-warehouse', '59 * * * *',\r\n                          'select public.sweep_collected_to_warehouse()');\r\n\r\n    perform cron.unschedule(jobid) from cron.job where jobname = 'shipments-enroute';\r\n    perform cron.schedule('shipments-enroute', '5 * * * *',\r\n                          'select public.sweep_warehouse_to_enroute()');\r\n  else\r\n    raise notice 'pg_cron not installed - status sweeps must be run manually';\r\n  end if;\r\nend $$;\r\n\n\n-- One customer, one record, however many times they book.\r\n--\r\n-- Today sixty shipments produce fifty-eight \"customers\". Nothing groups them\r\n-- reliably: website and app bookings never set user_id, so every one is a\r\n-- guest; thirty-one of sixty carry no email, so a key built as\r\n-- user_id -> email -> phone silently switches identifier between two bookings\r\n-- by the same person; and phone numbers are stored in three different shapes\r\n-- (+353…, 0…, and worse), so even the phone does not match itself.\r\n--\r\n-- The customer reference cannot fix this and was never going to. MAR09266988\r\n-- encodes the month and year of the booking, so it identifies a *booking*.\r\n-- Two bookings by one person in different months have different references by\r\n-- design. It stays exactly as it is — it is already printed on paperwork — and\r\n-- customers get their own stable code alongside it.\r\n--\r\n-- Identity is the phone number first, email second, per the agreed rule.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Normalising the things people are identified by\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The comparable part of a phone number: its last nine digits.\r\n *\r\n * That is what survives the ways one number gets written down. +353 83 425 2477,\r\n * 083 425 2477 and 00353834252477 all reduce to 834252477. Nine is chosen\r\n * because it is short enough to ignore every country and trunk prefix in use\r\n * here and long enough that two different subscribers will not collide.\r\n */\r\ncreate or replace function public.phone_identity_key(p_phone text)\r\nreturns text\r\nlanguage sql\r\nimmutable\r\nset search_path = public\r\nas $$\r\n  select case\r\n    when length(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')) >= 9\r\n      then right(regexp_replace(p_phone, '[^0-9]', '', 'g'), 9)\r\n    else nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), '')\r\n  end;\r\n$$;\r\n\r\ncreate or replace function public.email_identity_key(p_email text)\r\nreturns text\r\nlanguage sql\r\nimmutable\r\nset search_path = public\r\nas $$\r\n  select nullif(lower(trim(coalesce(p_email, ''))), '');\r\n$$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. The customer\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.customers (\r\n  id uuid primary key default gen_random_uuid(),\r\n  -- Stable for the life of the customer. Never encodes a date.\r\n  customer_code text not null unique,\r\n  full_name text,\r\n  email text,\r\n  phone text,\r\n  -- Generated, so they can never drift out of step with the raw values.\r\n  phone_key text generated always as (public.phone_identity_key(phone)) stored,\r\n  email_key text generated always as (public.email_identity_key(email)) stored,\r\n  country text,\r\n  pickup_address text,\r\n  pickup_city text,\r\n  pickup_postcode text,\r\n  -- Set once the customer signs up; a guest customer has none.\r\n  profile_id uuid references public.profiles(id) on delete set null,\r\n  notes text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- Partial uniques: two customers may both have no phone, but no two may share\r\n-- one. This is what stops a duplicate being created under a race.\r\ncreate unique index if not exists customers_phone_key_idx\r\n  on public.customers (phone_key) where phone_key is not null;\r\ncreate unique index if not exists customers_email_key_idx\r\n  on public.customers (email_key) where email_key is not null;\r\n-- Deliberately NOT unique. One account books for several people — a customer\r\n-- ordering for their mother and for themselves is two customers on one login —\r\n-- so a profile may be attached to more than one customer record.\r\ndrop index if exists public.customers_profile_idx;\r\ncreate index if not exists customers_profile_idx\r\n  on public.customers (profile_id) where profile_id is not null;\r\n\r\nalter table public.shipments\r\n  add column if not exists customer_id uuid references public.customers(id) on delete set null;\r\ncreate index if not exists shipments_customer_idx on public.shipments(customer_id)\r\n  where deleted_at is null;\r\n\r\ndo $$\r\nbegin\r\n  if to_regclass('public.custom_quotes') is not null then\r\n    execute 'alter table public.custom_quotes\r\n             add column if not exists customer_id uuid references public.customers(id) on delete set null';\r\n    execute 'create index if not exists custom_quotes_customer_idx on public.custom_quotes(customer_id)';\r\n  end if;\r\nend $$;\r\n\r\ncreate sequence if not exists public.customer_code_seq start 1;\r\n\r\n/**\r\n * A readable, stable customer code: three letters of their name and a running\r\n * number — MAR00042.\r\n *\r\n * Deliberately shaped like the booking reference so staff read them the same\r\n * way, and deliberately without a date so it never changes.\r\n */\r\ncreate or replace function public.next_customer_code(p_name text)\r\nreturns text\r\nlanguage sql\r\nvolatile\r\nset search_path = public\r\nas $$\r\n  select rpad(\r\n           coalesce(nullif(upper(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z]', '', 'g')), ''), 'CUS'),\r\n           3, 'X')\r\n         || lpad(nextval('public.customer_code_seq')::text, 5, '0');\r\n$$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Resolving a booking to a customer\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Find the customer these details belong to, or create them.\r\n *\r\n * Phone wins, then email. A signed-in profile is attached to whoever is found\r\n * but never used to identify them — see below. Details that arrive fuller\r\n * than what is on file fill the gaps — a second booking that carries an email\r\n * where the first did not should complete the record rather than fork it — but\r\n * never blank out something already known.\r\n */\r\ncreate or replace function public.resolve_customer(\r\n  p_name text default null,\r\n  p_email text default null,\r\n  p_phone text default null,\r\n  p_country text default null,\r\n  p_address text default null,\r\n  p_city text default null,\r\n  p_postcode text default null,\r\n  p_profile_id uuid default null\r\n) returns uuid\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_phone_key text := public.phone_identity_key(p_phone);\r\n  v_email_key text := public.email_identity_key(p_email);\r\n  v_id uuid;\r\n  -- Not every user_id on a shipment has a profiles row behind it: live data\r\n  -- carries ids for users whose profile was never created or has since gone.\r\n  -- Passing one straight through fails the foreign key and takes the whole\r\n  -- backfill with it, so an id that does not resolve is treated as no id —\r\n  -- the customer is still created, just without a profile attached.\r\n  v_profile_id uuid := (select p.id from public.profiles p where p.id = p_profile_id);\r\nbegin\r\n  if v_phone_key is not null then\r\n    select id into v_id from public.customers where phone_key = v_phone_key limit 1;\r\n  end if;\r\n  if v_id is null and v_email_key is not null then\r\n    select id into v_id from public.customers where email_key = v_email_key limit 1;\r\n  end if;\r\n  -- Deliberately no fallback to the profile. Matching on \"same login\" merged\r\n  -- an account holder's own booking with one they made for somebody else —\r\n  -- two different names, two different phone numbers, one customer. The login\r\n  -- says who placed the booking, not who the customer is.\r\n\r\n  if v_id is null then\r\n    -- Two bookings by one customer landing at once would both reach here.\r\n    -- Rather than guess which partial unique index will fire — phone, email or\r\n    -- profile — let the insert fail and pick up the row that won. ON CONFLICT\r\n    -- can only infer one index, so it would miss the other two.\r\n    begin\r\n      insert into public.customers (customer_code, full_name, email, phone, country,\r\n                                    pickup_address, pickup_city, pickup_postcode, profile_id)\r\n      values (public.next_customer_code(p_name), nullif(trim(coalesce(p_name, '')), ''),\r\n              nullif(trim(coalesce(p_email, '')), ''), nullif(trim(coalesce(p_phone, '')), ''),\r\n              nullif(trim(coalesce(p_country, '')), ''), nullif(trim(coalesce(p_address, '')), ''),\r\n              nullif(trim(coalesce(p_city, '')), ''), nullif(trim(coalesce(p_postcode, '')), ''),\r\n              v_profile_id)\r\n      returning id into v_id;\r\n    exception when unique_violation then\r\n      select id into v_id from public.customers\r\n       where (v_phone_key is not null and phone_key = v_phone_key)\r\n          or (v_email_key is not null and email_key = v_email_key)\r\n       limit 1;\r\n      if v_id is null then raise; end if;\r\n    end;\r\n  else\r\n    update public.customers set\r\n      full_name = coalesce(full_name, nullif(trim(coalesce(p_name, '')), '')),\r\n      email = coalesce(email, nullif(trim(coalesce(p_email, '')), '')),\r\n      phone = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')),\r\n      country = coalesce(country, nullif(trim(coalesce(p_country, '')), '')),\r\n      pickup_address = coalesce(pickup_address, nullif(trim(coalesce(p_address, '')), '')),\r\n      pickup_city = coalesce(pickup_city, nullif(trim(coalesce(p_city, '')), '')),\r\n      pickup_postcode = coalesce(pickup_postcode, nullif(trim(coalesce(p_postcode, '')), '')),\r\n      profile_id = coalesce(profile_id, v_profile_id),\r\n      updated_at = now()\r\n    where id = v_id;\r\n  end if;\r\n\r\n  return v_id;\r\nend $$;\r\n\r\n/**\r\n * Every booking joins its customer, whichever door it came in by.\r\n *\r\n * A trigger rather than an edit to each booking routine: bookings arrive from\r\n * the website, the customer app, the WhatsApp bot and manual admin entry, and\r\n * only a trigger catches all of them and anything added later.\r\n */\r\ncreate or replace function public.link_shipment_customer()\r\nreturns trigger\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_sender jsonb := coalesce(new.metadata->'sender', new.metadata->'senderDetails', '{}'::jsonb);\r\n  v_name text := coalesce(\r\n    nullif(trim(v_sender->>'name'), ''),\r\n    nullif(trim(concat_ws(' ', v_sender->>'firstName', v_sender->>'lastName')), ''));\r\nbegin\r\n  if new.customer_id is not null then\r\n    return new;\r\n  end if;\r\n\r\n  new.customer_id := public.resolve_customer(\r\n    v_name,\r\n    v_sender->>'email',\r\n    coalesce(v_sender->>'phone', new.metadata->>'whatsappNumber'),\r\n    coalesce(v_sender->>'country', new.origin),\r\n    v_sender->>'address',\r\n    v_sender->>'city',\r\n    coalesce(v_sender->>'postcode', v_sender->>'postalCode'),\r\n    new.user_id);\r\n\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists shipments_link_customer on public.shipments;\r\ncreate trigger shipments_link_customer\r\n  before insert or update of metadata, user_id on public.shipments\r\n  for each row\r\n  execute function public.link_shipment_customer();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Backfill, and a report of what it merged\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Link every existing shipment to a customer, merging as it goes.\r\n *\r\n * Ordered oldest first so the earliest booking names the customer and their\r\n * code, which keeps the codes in a sensible order and means the name on file\r\n * is the one they first gave.\r\n */\r\ncreate or replace function public.backfill_customers()\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_row record;\r\n  v_linked integer := 0;\r\n  v_before integer;\r\n  v_after integer;\r\nbegin\r\n  if auth.uid() is not null and not public.is_operations_admin() then\r\n    raise exception 'Admin access required' using errcode = '42501';\r\n  end if;\r\n\r\n  select count(*) into v_before from public.customers;\r\n\r\n  for v_row in\r\n    select id from public.shipments\r\n     where customer_id is null and deleted_at is null\r\n     order by created_at\r\n  loop\r\n    -- The trigger does the work; touching metadata is what fires it.\r\n    update public.shipments set metadata = metadata where id = v_row.id;\r\n    v_linked := v_linked + 1;\r\n  end loop;\r\n\r\n  select count(*) into v_after from public.customers;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentsLinked', v_linked,\r\n    'customersBefore', v_before,\r\n    'customersAfter', v_after,\r\n    'customersCreated', v_after - v_before);\r\nend $$;\r\n\r\nrevoke all on function public.backfill_customers() from public, anon;\r\ngrant execute on function public.backfill_customers() to authenticated;\r\n\r\n/**\r\n * What the merge actually did: every customer holding more than one booking,\r\n * with the distinct names, emails and phones that were folded together.\r\n *\r\n * This is the check on the automatic merge — a row here listing two different\r\n * people's names is the signal that a shared phone number merged two\r\n * customers, and admin can split them.\r\n */\r\ncreate or replace function public.customer_merge_report()\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select coalesce(jsonb_agg(r order by r->>'shipments' desc), '[]'::jsonb)\r\n  from (\r\n    select jsonb_build_object(\r\n      'customerId', c.id,\r\n      'customerCode', c.customer_code,\r\n      'name', c.full_name,\r\n      'phone', c.phone,\r\n      'email', c.email,\r\n      'shipments', count(s.id),\r\n      'distinctNames', (select coalesce(jsonb_agg(distinct n), '[]'::jsonb) from (\r\n         select coalesce(nullif(trim(s2.metadata->'sender'->>'name'), ''),\r\n                nullif(trim(concat_ws(' ', s2.metadata->'sender'->>'firstName',\r\n                                           s2.metadata->'sender'->>'lastName')), '')) as n\r\n         from public.shipments s2 where s2.customer_id = c.id) x where n is not null),\r\n      'distinctPhones', (select coalesce(jsonb_agg(distinct p), '[]'::jsonb) from (\r\n         select nullif(trim(s3.metadata->'sender'->>'phone'), '') as p\r\n         from public.shipments s3 where s3.customer_id = c.id) y where p is not null)\r\n    ) as r\r\n    from public.customers c\r\n    join public.shipments s on s.customer_id = c.id and s.deleted_at is null\r\n    group by c.id, c.customer_code, c.full_name, c.phone, c.email\r\n    having count(s.id) > 1\r\n  ) grouped;\r\n$$;\r\n\r\nrevoke all on function public.customer_merge_report() from public, anon;\r\ngrant execute on function public.customer_merge_report() to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. Access\r\n-- ---------------------------------------------------------------------------\r\n\r\nalter table public.customers enable row level security;\r\n\r\ndrop policy if exists \"Staff manage customers\" on public.customers;\r\ncreate policy \"Staff manage customers\" on public.customers\r\n  for all to authenticated\r\n  using (public.is_operations_admin() or public.is_finance_staff())\r\n  with check (public.is_operations_admin() or public.is_finance_staff());\r\n\r\n-- A signed-in customer may read their own record, which is what lets the app\r\n-- and the website show them everything booked under it rather than only the\r\n-- shipments that happen to carry their user_id.\r\ndrop policy if exists \"Customers read own record\" on public.customers;\r\ncreate policy \"Customers read own record\" on public.customers\r\n  for select to authenticated\r\n  using (profile_id = auth.uid());\r\n\r\n/**\r\n * The portal shows a customer everything booked under their record.\r\n *\r\n * Until now it could only show shipments carrying their user_id, and website\r\n * bookings never set one — so a customer who booked as a guest and then\r\n * created an account saw an empty account. RLS policies are OR'd together, so\r\n * this widens what they can see without loosening anything already in place.\r\n */\r\ndrop policy if exists \"Customers read shipments on their record\" on public.shipments;\r\ncreate policy \"Customers read shipments on their record\" on public.shipments\r\n  for select to authenticated\r\n  using (\r\n    customer_id is not null\r\n    and customer_id in (select id from public.customers where profile_id = auth.uid())\r\n  );\r\n\r\n/**\r\n * Signing up claims the bookings already made with that phone or email.\r\n *\r\n * The whole point of unifying customers is undone if creating an account makes\r\n * a fifty-ninth record. A new or updated profile is attached to the customer\r\n * that already matches it, and only creates one when nothing does.\r\n */\r\ncreate or replace function public.link_profile_customer()\r\nreturns trigger\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_customer uuid;\r\nbegin\r\n  -- Staff are not customers.\r\n  if coalesce(new.is_admin, false)\r\n     or lower(coalesce(new.role, 'customer')) in ('admin', 'driver', 'finance', 'logistics', 'dispatcher') then\r\n    return new;\r\n  end if;\r\n\r\n  v_customer := public.resolve_customer(\r\n    new.full_name, new.email, new.phone_number, new.country,\r\n    new.pickup_address, new.pickup_city, null, new.id);\r\n\r\n  -- Hand them the bookings they made before they had an account.\r\n  --\r\n  -- Setting user_id, rather than only linking the customer, is deliberate:\r\n  -- every screen in the app and on the website already asks \"shipments where\r\n  -- user_id is me\". Claiming the rows here makes all of them correct at once,\r\n  -- instead of a dozen queries each needing to learn about customers and one\r\n  -- of them being missed. Only unclaimed rows are touched, so a shipment that\r\n  -- already belongs to somebody is never reassigned.\r\n  update public.shipments\r\n     set user_id = new.id\r\n   where user_id is null\r\n     and deleted_at is null\r\n     and customer_id is not null\r\n     and (customer_id = v_customer\r\n          or customer_id in (select id from public.customers where profile_id = new.id));\r\n\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists profiles_link_customer on public.profiles;\r\ncreate trigger profiles_link_customer\r\n  after insert or update of email, phone_number on public.profiles\r\n  for each row\r\n  execute function public.link_profile_customer();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- F. What the admin screens read\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The customer list: one row per customer, with the totals staff scan for.\r\n *\r\n * This replaces admin_customer_records, whose job was to *reconstruct* customers\r\n * from scattered booking details every time it ran. That reconstruction is what\r\n * produced fifty-eight customers from sixty shipments. Identity is a stored\r\n * fact now, so this only has to add up what hangs off it.\r\n */\r\ncreate or replace function public.admin_customer_list()\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select case when not (public.is_operations_admin() or public.is_finance_staff())\r\n    then jsonb_build_object('error', 'Admin or finance access required')\r\n    else coalesce((\r\n      select jsonb_agg(row order by row->>'lastActivity' desc nulls last)\r\n      from (\r\n        select jsonb_build_object(\r\n          'key', c.id,\r\n          'customerId', c.id,\r\n          'profileId', c.profile_id,\r\n          'customerCode', c.customer_code,\r\n          'fullName', coalesce(c.full_name, 'Unknown customer'),\r\n          'email', c.email,\r\n          'phone', c.phone,\r\n          'country', c.country,\r\n          'pickupAddress', nullif(trim(concat_ws(', ', c.pickup_address, c.pickup_city)), ''),\r\n          'shipmentCount', count(distinct s.id),\r\n          'quoteCount', 0,\r\n          'lifetimeValue', coalesce(sum(inv.total), 0),\r\n          'outstanding', coalesce(sum(inv.total), 0) - coalesce(sum(inv.paid), 0),\r\n          'currency', coalesce(max(inv.currency), 'GBP'),\r\n          'lastBooking', max(s.created_at),\r\n          'lastActivity', greatest(coalesce(max(s.created_at), c.created_at), c.created_at),\r\n          'active', true\r\n        ) as row\r\n        from public.customers c\r\n        left join public.shipments s\r\n          on s.customer_id = c.id and s.deleted_at is null\r\n        left join lateral (\r\n          select\r\n            coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                      from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\r\n                                                     then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n            - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) as total,\r\n            coalesce((select sum(coalesce((p->>'amount')::numeric,0))\r\n                      from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\r\n                                                     then s.metadata->'invoice'->'payments' else '[]'::jsonb end) p), 0) as paid,\r\n            s.metadata->'invoice'->>'currency' as currency\r\n        ) inv on true\r\n        group by c.id, c.profile_id, c.customer_code, c.full_name, c.email, c.phone,\r\n                 c.country, c.pickup_address, c.pickup_city, c.created_at\r\n      ) grouped\r\n    ), '[]'::jsonb)\r\n  end;\r\n$$;\r\n\r\nrevoke all on function public.admin_customer_list() from public, anon;\r\ngrant execute on function public.admin_customer_list() to authenticated;\r\n\r\n/**\r\n * A customer's statement: every charge and every payment, oldest first, with a\r\n * running balance.\r\n *\r\n * Built from the same metadata.invoice the invoice, the app and the website all\r\n * read, so the statement cannot disagree with the documents it summarises.\r\n */\r\ncreate or replace function public.customer_statement(p_customer_id uuid)\r\nreturns jsonb\r\nlanguage plpgsql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_rows jsonb;\r\n  v_allowed boolean;\r\nbegin\r\n  select public.is_operations_admin() or public.is_finance_staff()\r\n         or exists (select 1 from public.customers c\r\n                     where c.id = p_customer_id and c.profile_id = auth.uid())\r\n    into v_allowed;\r\n  if not v_allowed then\r\n    raise exception 'Not your statement' using errcode = '42501';\r\n  end if;\r\n\r\n  with charges as (\r\n    select s.id as shipment_id, s.created_at as at,\r\n           coalesce(s.metadata->'invoice'->>'invoiceNumber',\r\n                    'INV-' || coalesce(s.customer_reference, s.tracking_number, '')) as ref,\r\n           'charge' as kind,\r\n           coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\r\n                                                    then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n           - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) as amount,\r\n           coalesce(s.metadata->'invoice'->>'currency', 'GBP') as currency,\r\n           null::text as method\r\n      from public.shipments s\r\n     where s.customer_id = p_customer_id and s.deleted_at is null\r\n       and s.metadata->'invoice' is not null\r\n  ),\r\n  credits as (\r\n    select s.id as shipment_id,\r\n           coalesce((p->>'date')::timestamptz, s.created_at) as at,\r\n           coalesce(s.metadata->'invoice'->>'invoiceNumber', s.tracking_number) as ref,\r\n           'payment' as kind,\r\n           -coalesce((p->>'amount')::numeric, 0) as amount,\r\n           coalesce(s.metadata->'invoice'->>'currency', 'GBP') as currency,\r\n           p->>'method' as method\r\n      from public.shipments s\r\n      cross join lateral jsonb_array_elements(\r\n        case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\r\n             then s.metadata->'invoice'->'payments' else '[]'::jsonb end) p\r\n     where s.customer_id = p_customer_id and s.deleted_at is null\r\n  ),\r\n  ordered as (\r\n    -- Order by the calendar day, then charge before payment.\r\n    --\r\n    -- Not by timestamp: a payment carries a plain date, which is midnight,\r\n    -- while the invoice it settles carries the booking's real time of day. Any\r\n    -- payment therefore sorts ahead of the invoice it pays, and the statement\r\n    -- opens hundreds in credit before the first bill is raised.\r\n    select *, sum(amount) over (order by at::date, kind, at\r\n                                rows between unbounded preceding and current row) as balance\r\n      from (select * from charges union all select * from credits) both_sides\r\n  )\r\n  select coalesce(jsonb_agg(jsonb_build_object(\r\n           'shipmentId', shipment_id, 'at', at, 'reference', ref, 'kind', kind,\r\n           'amount', amount, 'currency', currency, 'method', method, 'balance', balance\r\n         ) order by at::date, kind, at), '[]'::jsonb)\r\n    into v_rows from ordered;\r\n\r\n  return v_rows;\r\nend $$;\r\n\r\nrevoke all on function public.customer_statement(uuid) from public, anon;\r\ngrant execute on function public.customer_statement(uuid) to authenticated;\r\n\n\n-- Deleting things, and seeing a collection period as one job.\r\n--\r\n-- Two gaps.\r\n--\r\n-- The app can create or change twenty tables and delete from none of them.\r\n-- Some of that is right: audit_logs, payments, receipts and proof photos are\r\n-- the record of what happened, and a business that can quietly delete those\r\n-- cannot answer a dispute. Everything else — a quote raised in error, a\r\n-- duplicate pickup zone, an expense typed twice — needs a way out, and only\r\n-- `shipments` had one.\r\n--\r\n-- Every delete here is soft. A shipment carries an invoice, a delivery note, a\r\n-- driver's photos and a customer's payment; removing the row would orphan all\r\n-- of it, and \"we deleted it\" is not an answer when the customer rings.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Somewhere to record a deletion\r\n-- ---------------------------------------------------------------------------\r\n\r\ndo $$\r\ndeclare\r\n  t text;\r\n  -- Deliberately excludes audit_logs, payments, receipts, driver_proofs and\r\n  -- driver_signatures. Those are evidence, not content.\r\n  targets text[] := array[\r\n    'custom_quotes', 'finance_expenses', 'pickup_zones', 'collection_schedules',\r\n    'collection_periods', 'customers', 'staff_messages', 'collection_runs'\r\n  ];\r\nbegin\r\n  foreach t in array targets loop\r\n    if to_regclass('public.' || t) is not null then\r\n      execute format('alter table public.%I add column if not exists deleted_at timestamptz', t);\r\n      execute format('alter table public.%I add column if not exists deleted_by uuid references auth.users(id) on delete set null', t);\r\n      execute format('create index if not exists %I on public.%I (deleted_at) where deleted_at is null',\r\n                     t || '_live_idx', t);\r\n    end if;\r\n  end loop;\r\nend $$;\r\n\r\n-- shipments had deleted_at from the start but never recorded who.\r\nalter table public.shipments\r\n  add column if not exists deleted_by uuid references auth.users(id) on delete set null;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. One way to delete, and to undo it\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Soft-delete (or restore) rows, in bulk.\r\n *\r\n * One routine rather than a delete endpoint per table: the rule about what may\r\n * be deleted, and by whom, then lives in exactly one place. The table name is\r\n * checked against a whitelist rather than interpolated blindly — this takes a\r\n * table name from the client, and that is only safe if the set of acceptable\r\n * answers is fixed here.\r\n *\r\n * `p_deleted => false` restores, which is the point of soft deletion: a\r\n * mistaken bulk delete is undone with the same call.\r\n */\r\ncreate or replace function public.set_records_deleted(\r\n  p_table text,\r\n  p_ids uuid[],\r\n  p_deleted boolean default true\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_allowed text[] := array[\r\n    'shipments', 'custom_quotes', 'finance_expenses', 'pickup_zones',\r\n    'collection_schedules', 'collection_periods', 'customers', 'staff_messages',\r\n    'collection_runs'\r\n  ];\r\n  v_table text := lower(trim(coalesce(p_table, '')));\r\n  v_count integer := 0;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Admin or finance access required' using errcode = '42501';\r\n  end if;\r\n  if not (v_table = any(v_allowed)) then\r\n    raise exception 'Refusing to delete from %', p_table using errcode = '42501';\r\n  end if;\r\n  if p_ids is null or array_length(p_ids, 1) is null then\r\n    return jsonb_build_object('changed', 0);\r\n  end if;\r\n\r\n  execute format(\r\n    'update public.%I set deleted_at = %s, deleted_by = %s where id = any($1)',\r\n    v_table,\r\n    case when p_deleted then 'now()' else 'null' end,\r\n    case when p_deleted then 'auth.uid()' else 'null' end)\r\n  using p_ids;\r\n\r\n  get diagnostics v_count = row_count;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when p_deleted then 'SOFT_DELETE' else 'RESTORE' end,\r\n          upper(v_table), null,\r\n          jsonb_build_object('ids', to_jsonb(p_ids), 'count', v_count));\r\n\r\n  return jsonb_build_object('changed', v_count, 'deleted', p_deleted, 'table', v_table);\r\nend $$;\r\n\r\nrevoke all on function public.set_records_deleted(text, uuid[], boolean) from public, anon;\r\ngrant execute on function public.set_records_deleted(text, uuid[], boolean) to authenticated;\r\n\r\n/**\r\n * Change the same thing on many shipments at once.\r\n *\r\n * Only the fields it is safe to set in bulk: what stage they are at, and which\r\n * collection they belong to. Addresses, prices and contents are per-shipment\r\n * and are edited one at a time on purpose — a bulk edit of those is a bulk\r\n * mistake. Null means \"leave alone\", so one call can move a period without\r\n * touching status.\r\n */\r\ncreate or replace function public.bulk_update_shipments(\r\n  p_ids uuid[],\r\n  p_status text default null,\r\n  p_collection_schedule_id uuid default null,\r\n  p_collection_period_id uuid default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_count integer := 0;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Admin or finance access required' using errcode = '42501';\r\n  end if;\r\n  if p_ids is null or array_length(p_ids, 1) is null then\r\n    return jsonb_build_object('changed', 0);\r\n  end if;\r\n\r\n  update public.shipments s set\r\n    status = coalesce(nullif(trim(coalesce(p_status, '')), ''), s.status),\r\n    collection_schedule_id = coalesce(p_collection_schedule_id, s.collection_schedule_id),\r\n    collection_period_id = coalesce(p_collection_period_id, s.collection_period_id),\r\n    updated_at = now()\r\n  where s.id = any(p_ids)\r\n    and s.deleted_at is null;\r\n\r\n  get diagnostics v_count = row_count;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'BULK_UPDATE', 'SHIPMENT', null,\r\n          jsonb_build_object('count', v_count, 'status', p_status,\r\n                             'scheduleId', p_collection_schedule_id,\r\n                             'periodId', p_collection_period_id));\r\n\r\n  return jsonb_build_object('changed', v_count);\r\nend $$;\r\n\r\nrevoke all on function public.bulk_update_shipments(uuid[], text, uuid, uuid) from public, anon;\r\ngrant execute on function public.bulk_update_shipments(uuid[], text, uuid, uuid) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. A collection period as one job\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Every collection period with its numbers, newest first.\r\n *\r\n * A period is how this business actually works — bookings open, they fill, the\r\n * container goes — so it is the unit staff should see, rather than one endless\r\n * list of every shipment ever booked.\r\n *\r\n * Money is read from metadata.invoice, the same place the invoice, the app and\r\n * the website read it, so the period's totals and the documents inside it\r\n * cannot disagree.\r\n */\r\ncreate or replace function public.collection_period_summary()\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select case when not (public.is_operations_admin() or public.is_finance_staff())\r\n    then jsonb_build_object('error', 'Admin or finance access required')\r\n    else coalesce((\r\n      select jsonb_agg(row order by row->>'sortKey' desc)\r\n      from (\r\n        select jsonb_build_object(\r\n          'periodId', p.id,\r\n          'name', p.name,\r\n          'month', p.month,\r\n          'year', p.year,\r\n          'status', p.status,\r\n          -- Sorted by the period's last scheduled collection, not by its\r\n          -- month name: `month` is text (\"May\", \"June\"), so anything\r\n          -- alphabetical puts April after August. Periods with nothing\r\n          -- scheduled yet fall back to their year.\r\n          'sortKey', coalesce(\r\n            to_char((select max(cs.pickup_on) from public.collection_schedules cs\r\n                     join public.collection_periods cp on cp.id = cs.collection_period_id\r\n                     where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n                       and cp.year = p.year), 'YYYY-MM-DD'),\r\n            lpad(coalesce(p.year, 0)::text, 4, '0') || '-00-00'),\r\n          -- Routes are matched on month and year, not only on the period id.\r\n          -- Live data has two September 2026 periods differing by nothing but\r\n          -- capitalisation: one holds every booking and no schedule, the other\r\n          -- every schedule and no booking. Matching on the id alone shows a\r\n          -- period full of work as having no routes at all.\r\n          'routes', coalesce((\r\n            select jsonb_agg(distinct cs.route)\r\n            from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year\r\n              and cs.route is not null and cs.deleted_at is null), '[]'::jsonb),\r\n          'firstCollection', (\r\n            select min(cs.pickup_on) from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year),\r\n          'lastCollection', (\r\n            select max(cs.pickup_on) from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year),\r\n          'shipments', count(s.id),\r\n          'collected', count(s.id) filter (where lower(coalesce(s.status, '')) in\r\n            ('collected', 'at warehouse', 'enroute to zimbabwe', 'in transit', 'delivered')),\r\n          -- Totals per currency, never added together: a period routinely\r\n          -- holds UK and Irish collections, and pounds plus euros is a number\r\n          -- that is not money in either.\r\n          'byCurrency', coalesce((\r\n            select jsonb_agg(jsonb_build_object(\r\n                     'currency', t.cur, 'invoiced', t.inv, 'paid', t.pd,\r\n                     'outstanding', greatest(0, t.inv - t.pd))\r\n                   order by t.inv desc)\r\n            from (\r\n              select coalesce(s2.metadata->'invoice'->>'currency', 'GBP') as cur,\r\n                sum(coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'items')='array'\r\n                                                    then s2.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n                    - coalesce((s2.metadata->'invoice'->>'discount')::numeric, 0)) as inv,\r\n                sum(coalesce((select sum(coalesce((pay->>'amount')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'payments')='array'\r\n                                                    then s2.metadata->'invoice'->'payments' else '[]'::jsonb end) pay), 0)) as pd\r\n              from public.shipments s2\r\n              where s2.collection_period_id = p.id and s2.deleted_at is null\r\n                -- A deleted invoice is not money owed. The screens filter it\r\n                -- out, so a period total that still counted it disagreed with\r\n                -- the list underneath it.\r\n                and s2.metadata->'invoice'->>'deletedAt' is null\r\n              group by 1\r\n              having sum(coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'items')='array'\r\n                                                    then s2.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)) > 0\r\n            ) t), '[]'::jsonb),\r\n          'invoiced', coalesce(sum(inv.total), 0),\r\n          'paid', coalesce(sum(inv.paid), 0),\r\n          'outstanding', greatest(0, coalesce(sum(inv.total), 0) - coalesce(sum(inv.paid), 0)),\r\n          -- \"Cleared\" means nothing left to pay on that shipment.\r\n          'cleared', count(s.id) filter (where inv.total > 0 and inv.paid >= inv.total - 0.005),\r\n          'unpaid', count(s.id) filter (where inv.total > 0 and inv.paid <= 0.005),\r\n          'currency', coalesce(max(inv.currency), 'GBP')\r\n        ) as row\r\n        from public.collection_periods p\r\n        left join public.shipments s\r\n          on s.collection_period_id = p.id and s.deleted_at is null\r\n        left join lateral (\r\n          select\r\n            case when s.metadata->'invoice'->>'deletedAt' is not null then 0 else\r\n              coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\r\n                                                       then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n              - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) end as total,\r\n            case when s.metadata->'invoice'->>'deletedAt' is not null then 0 else\r\n              coalesce((select sum(coalesce((pay->>'amount')::numeric,0))\r\n                        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\r\n                                                       then s.metadata->'invoice'->'payments' else '[]'::jsonb end) pay), 0) end as paid,\r\n            s.metadata->'invoice'->>'currency' as currency\r\n        ) inv on true\r\n        where p.deleted_at is null\r\n        group by p.id, p.name, p.month, p.year, p.status\r\n      ) grouped\r\n    ), '[]'::jsonb)\r\n  end;\r\n$$;\r\n\r\nrevoke all on function public.collection_period_summary() from public, anon;\r\ngrant execute on function public.collection_period_summary() to authenticated;\r\n\r\n/**\r\n * The collection schedules that belong to a period, by month and year.\r\n *\r\n * Not by period id, for the same reason the summary does not: live data has\r\n * two September 2026 periods differing only by capitalisation, one carrying\r\n * every booking and the other every route. Looking up by id leaves the period\r\n * staff are working in with no routes to assign anything to.\r\n */\r\ncreate or replace function public.period_schedules(p_period_id uuid)\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select coalesce((\r\n    select jsonb_agg(jsonb_build_object(\r\n      'id', cs.id, 'route', cs.route, 'country', cs.country, 'pickup_on', cs.pickup_on)\r\n      order by cs.pickup_on nulls last, cs.route)\r\n    from public.collection_schedules cs\r\n    join public.collection_periods cp on cp.id = cs.collection_period_id\r\n    join public.collection_periods target on target.id = p_period_id\r\n    where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(target.month, '')))\r\n      and cp.year = target.year\r\n      and cs.deleted_at is null\r\n  ), '[]'::jsonb);\r\n$$;\r\n\r\nrevoke all on function public.period_schedules(uuid) from public, anon;\r\ngrant execute on function public.period_schedules(uuid) to authenticated;\r\n\n\n-- Invoices and delivery notes are raised by staff, not by the booking form.\r\n--\r\n-- Until now a booking issued its own invoice. `create_customer_booking_legacy`\r\n-- stamped an invoice number, an issue date and a due date the instant a\r\n-- customer pressed Book, so 77 of the 107 live shipments carry an invoice that\r\n-- nobody in the office ever looked at. That is backwards: the confirmation call\r\n-- is where the contents and the price are established, and an invoice raised\r\n-- before that call is a document the business has not agreed to.\r\n--\r\n-- The booking still *prices* the shipment. It must — `metadata.invoice.items`\r\n-- is what the driver's goods list, the delivery note and two reporting views\r\n-- read, and emptying it would break all of them. What the booking stops doing\r\n-- is issuing. The invoice number is the line between the two:\r\n--\r\n--   items, currency, terms   ->  written at booking, as it always was\r\n--   invoiceNumber, issuedAt  ->  written only by public.issue_shipment_invoice\r\n--\r\n-- Nothing already issued changes meaning. Every one of those 77 carries a\r\n-- number, so they all read as issued and stay exactly where they are — in the\r\n-- invoice lists, on the customer's account and in the period totals.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. The booking stops issuing\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Drop the three issuing fields from a freshly booked shipment.\r\n *\r\n * Written as an after-the-fact strip rather than an edit to the 11kb legacy\r\n * function body, so the pricing logic — which is correct and heavily depended\r\n * on — is not retyped and cannot be mistranscribed.\r\n */\r\ncreate or replace function public.create_customer_booking(p jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_result jsonb;\r\n  v_quote_id uuid := nullif(p->>'quoteId', '')::uuid;\r\n  v_quote public.custom_quotes%rowtype;\r\n  v_shipment_id uuid;\r\n  v_ship public.shipments%rowtype;\r\n  v_invoice jsonb;\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_item jsonb;\r\n  v_itemised numeric := 0;\r\n  v_line jsonb;\r\n  v_replaced boolean := false;\r\nbegin\r\n  -- Everything the previous version did stays exactly as it was.\r\n  v_result := public.create_customer_booking_v3(p);\r\n  v_shipment_id := nullif(v_result->>'id', '')::uuid;\r\n\r\n  -- The booking priced the shipment; it does not get to issue the invoice.\r\n  if v_shipment_id is not null then\r\n    update public.shipments\r\n       set metadata = jsonb_set(\r\n             coalesce(metadata, '{}'::jsonb),\r\n             '{invoice}',\r\n             coalesce(metadata->'invoice', '{}'::jsonb)\r\n               - 'invoiceNumber' - 'issueDate' - 'dueDate',\r\n             true)\r\n     where id = v_shipment_id\r\n       and metadata->'invoice' is not null;\r\n  end if;\r\n\r\n  if v_quote_id is null then return v_result; end if;\r\n\r\n  select * into v_quote from public.custom_quotes where id = v_quote_id;\r\n  if not found or v_quote.quote_items is null or jsonb_array_length(v_quote.quote_items) = 0 then\r\n    return v_result;\r\n  end if;\r\n\r\n  -- Every item must carry its own price, and they must add up to the amount the\r\n  -- customer was quoted and agreed. If they do not, the single line stands:\r\n  -- silently re-pricing a booking to make a breakdown fit would be worse than\r\n  -- having no breakdown.\r\n  for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n    if coalesce((v_item->>'amount')::numeric, 0) <= 0 then return v_result; end if;\r\n    v_itemised := v_itemised + (v_item->>'amount')::numeric;\r\n  end loop;\r\n  if abs(v_itemised - coalesce(v_quote.quoted_amount, -1)) > 0.01 then return v_result; end if;\r\n\r\n  if v_shipment_id is null then return v_result; end if;\r\n  select * into v_ship from public.shipments where id = v_shipment_id for update;\r\n  if not found then return v_result; end if;\r\n\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n\r\n  -- Swap the one \"Approved quote: …\" line for the priced breakdown, leaving\r\n  -- every other line (drums, seals, door delivery) exactly where it was.\r\n  for v_line in select * from jsonb_array_elements(coalesce(v_invoice->'items', '[]'::jsonb)) loop\r\n    if not v_replaced and coalesce(v_line->>'description', '') like 'Approved quote:%' then\r\n      v_replaced := true;\r\n      for v_item in select * from jsonb_array_elements(v_quote.quote_items) loop\r\n        v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n          'description', left(coalesce(nullif(trim(v_item->>'description'), ''), 'Quoted item'), 200),\r\n          'quantity', 1,\r\n          'unitPrice', (v_item->>'amount')::numeric));\r\n      end loop;\r\n    else\r\n      v_lines := v_lines || jsonb_build_array(v_line);\r\n    end if;\r\n  end loop;\r\n  if not v_replaced then return v_result; end if;\r\n\r\n  v_invoice := jsonb_set(v_invoice, '{items}', v_lines, true);\r\n\r\n  update public.shipments\r\n     set metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{invoice}', v_invoice, true),\r\n         updated_at = now()\r\n   where id = v_shipment_id;\r\n\r\n  return v_result || jsonb_build_object('invoice', v_invoice);\r\nend $$;\r\n\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated, anon;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Staff raise the invoice\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Issue the invoice for a shipment.\r\n *\r\n * `p_invoice` is the whole invoice as the member of staff checked it — the\r\n * prefilled lines, corrected. The number, the dates and who issued it are set\r\n * here rather than by the client, so two people pressing Create at once cannot\r\n * mint the same invoice number, and so \"who raised this\" is not a claim the\r\n * phone makes about itself.\r\n *\r\n * Re-issuing an invoice that already has a number keeps that number. An invoice\r\n * number is what the customer quotes on the phone and what the payment\r\n * references; changing it because somebody re-opened the editor would strand\r\n * every payment already made against it.\r\n */\r\ncreate or replace function public.issue_shipment_invoice(\r\n  p_shipment_id uuid,\r\n  p_invoice jsonb default '{}'::jsonb\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_ship public.shipments%rowtype;\r\n  v_invoice jsonb;\r\n  v_number text;\r\n  v_actor uuid := auth.uid();\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Admin or finance access required' using errcode = '42501';\r\n  end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id for update;\r\n  if not found then\r\n    raise exception 'Shipment % not found', p_shipment_id using errcode = 'P0002';\r\n  end if;\r\n\r\n  -- Start from what was checked, falling back to what the booking priced.\r\n  v_invoice := coalesce(nullif(p_invoice, 'null'::jsonb), '{}'::jsonb);\r\n  if v_invoice = '{}'::jsonb then\r\n    v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n  end if;\r\n\r\n  -- An invoice with nothing on it is not an invoice.\r\n  if coalesce(jsonb_array_length(\r\n       case when jsonb_typeof(v_invoice->'items') = 'array' then v_invoice->'items' else '[]'::jsonb end\r\n     ), 0) = 0 then\r\n    raise exception 'Add at least one line before creating the invoice' using errcode = '22023';\r\n  end if;\r\n\r\n  v_number := nullif(trim(coalesce(\r\n    v_ship.metadata->'invoice'->>'invoiceNumber',\r\n    v_invoice->>'invoiceNumber')), '');\r\n  if v_number is null then\r\n    v_number := 'INV-' || coalesce(\r\n      nullif(trim(v_ship.customer_reference), ''),\r\n      replace(v_ship.tracking_number, 'ZIMSHIP-', ''),\r\n      to_char(now(), 'YYYYMMDDHH24MISS'));\r\n  end if;\r\n\r\n  v_invoice := v_invoice || jsonb_build_object(\r\n    'invoiceNumber', v_number,\r\n    'issueDate', coalesce(nullif(v_invoice->>'issueDate', ''), to_char(now(), 'YYYY-MM-DD')),\r\n    'dueDate', coalesce(nullif(v_invoice->>'dueDate', ''), to_char(now() + interval '14 days', 'YYYY-MM-DD')),\r\n    'issuedAt', coalesce(v_ship.metadata->'invoice'->>'issuedAt', to_char(now(), 'YYYY-MM-DD\"T\"HH24:MI:SSOF')),\r\n    'issuedBy', coalesce(v_ship.metadata->'invoice'->>'issuedBy', v_actor::text),\r\n    -- Raising it again un-deletes it, which is what pressing Create means.\r\n    'deletedAt', null);\r\n\r\n  update public.shipments\r\n     set metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{invoice}', v_invoice, true),\r\n         updated_at = now()\r\n   where id = p_shipment_id;\r\n\r\n  insert into public.shipment_events(shipment_id, event_type, actor_id, details)\r\n  values (p_shipment_id, 'invoice_issued', v_actor, jsonb_build_object('invoiceNumber', v_number));\r\n\r\n  return v_invoice;\r\nend $$;\r\n\r\nrevoke all on function public.issue_shipment_invoice(uuid, jsonb) from public, anon;\r\ngrant execute on function public.issue_shipment_invoice(uuid, jsonb) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Staff raise the delivery note\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Create the delivery note for a collected shipment.\r\n *\r\n * The note goes into `delivery_note_records`, the office document register, and\r\n * deliberately NOT into `public.delivery_notes`. Those two are easy to confuse\r\n * and are not the same thing: `delivery_notes` is the driver's proof at the\r\n * door, keyed to a run stop, with `stop_id` and `driver_id` both NOT NULL —\r\n * there is no honest way to write an office note into it, and inventing a stop\r\n * and a driver to satisfy the constraints would corrupt the driver's record of\r\n * what actually happened. `delivery_note_records` already carries exactly the\r\n * fields a printed note has: shipper, recipient, items, paid, balance due.\r\n *\r\n * The note is raised once the goods are in our hands, because that is the first\r\n * moment its contents are a fact rather than a plan. It needs the invoice\r\n * first — `invoice_number` is NOT NULL on the register, and a delivery note\r\n * that cannot name the invoice it belongs to is not much of a record.\r\n */\r\ncreate or replace function public.create_shipment_delivery_note(\r\n  p_shipment_id uuid\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_ship public.shipments%rowtype;\r\n  v_note public.delivery_note_records%rowtype;\r\n  v_reference text;\r\n  v_invoice_number text;\r\n  v_actor uuid := auth.uid();\r\n  v_recipient jsonb;\r\n  v_sender jsonb;\r\n  v_invoice jsonb;\r\n  v_total numeric;\r\n  v_paid numeric;\r\n  v_suffix integer := 0;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff() or public.is_staff_member()) then\r\n    raise exception 'Staff access required' using errcode = '42501';\r\n  end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id for update;\r\n  if not found then\r\n    raise exception 'Shipment % not found', p_shipment_id using errcode = 'P0002';\r\n  end if;\r\n\r\n  -- One note per shipment. Pressing the button twice returns the first one\r\n  -- rather than issuing a second note for the same goods.\r\n  select * into v_note from public.delivery_note_records\r\n   where shipment_id = p_shipment_id and voided_at is null\r\n   order by created_at limit 1;\r\n  if found then\r\n    return jsonb_build_object('noteId', v_note.id, 'reference', v_note.reference, 'created', false);\r\n  end if;\r\n\r\n  if v_ship.collected_at is null\r\n     and lower(coalesce(v_ship.status, '')) not in\r\n         ('collected', 'at warehouse', 'enroute to zimbabwe', 'in transit',\r\n          'zim warehouse', 'out for delivery', 'delivered') then\r\n    raise exception 'Collect the goods before raising the delivery note' using errcode = '22023';\r\n  end if;\r\n\r\n  v_invoice := coalesce(v_ship.metadata->'invoice', '{}'::jsonb);\r\n  v_invoice_number := nullif(trim(coalesce(v_invoice->>'invoiceNumber', '')), '');\r\n  if v_invoice_number is null then\r\n    raise exception 'Create the invoice before the delivery note' using errcode = '22023';\r\n  end if;\r\n\r\n  v_sender := coalesce(v_ship.metadata->'sender', v_ship.metadata->'senderDetails', '{}'::jsonb);\r\n  v_recipient := coalesce(v_ship.metadata->'recipient', v_ship.metadata->'receiverDetails', '{}'::jsonb);\r\n\r\n  select\r\n    coalesce(sum(coalesce((i->>'quantity')::numeric, 0) * coalesce((i->>'unitPrice')::numeric, 0)), 0)\r\n    - coalesce((v_invoice->>'discount')::numeric, 0)\r\n  into v_total\r\n  from jsonb_array_elements(\r\n    case when jsonb_typeof(v_invoice->'items') = 'array' then v_invoice->'items' else '[]'::jsonb end) i;\r\n\r\n  select coalesce(sum(coalesce((pay->>'amount')::numeric, 0)), 0) into v_paid\r\n  from jsonb_array_elements(\r\n    case when jsonb_typeof(v_invoice->'payments') = 'array' then v_invoice->'payments' else '[]'::jsonb end) pay;\r\n\r\n  -- REF as printed: first three letters of the shipper's given name, then the\r\n  -- invoice number. `reference` is unique on upper(reference), so a second note\r\n  -- against the same invoice takes the next load suffix rather than failing.\r\n  v_reference := upper(left(regexp_replace(coalesce(\r\n    nullif(trim(v_sender->>'firstName'), ''),\r\n    split_part(trim(coalesce(v_sender->>'name', 'ZIM')), ' ', 1)), '[^A-Za-z]', '', 'g') || 'XXX', 3))\r\n    || v_invoice_number;\r\n  while exists (select 1 from public.delivery_note_records\r\n                 where upper(reference) = upper(v_reference)) loop\r\n    v_suffix := v_suffix + 1;\r\n    if v_suffix > 25 then\r\n      raise exception 'Too many delivery notes already issued against %', v_invoice_number;\r\n    end if;\r\n    v_reference := upper(left(regexp_replace(coalesce(\r\n      nullif(trim(v_sender->>'firstName'), ''),\r\n      split_part(trim(coalesce(v_sender->>'name', 'ZIM')), ' ', 1)), '[^A-Za-z]', '', 'g') || 'XXX', 3))\r\n      || v_invoice_number || chr(64 + v_suffix);\r\n  end loop;\r\n\r\n  insert into public.delivery_note_records (\r\n    reference, invoice_number, load_suffix,\r\n    shipper_name, shipper_phone, shipper_address,\r\n    recipient_name, recipient_phone, recipient_address, recipient_city,\r\n    items, delivery_mode, paid, balance_due, note_date,\r\n    shipment_id, confirmed_by\r\n  ) values (\r\n    v_reference,\r\n    v_invoice_number,\r\n    case when v_suffix > 0 then chr(64 + v_suffix) else null end,\r\n    nullif(trim(coalesce(v_sender->>'name',\r\n      concat_ws(' ', v_sender->>'firstName', v_sender->>'lastName'))), ''),\r\n    nullif(trim(coalesce(v_sender->>'phone', '')), ''),\r\n    nullif(trim(concat_ws(', ', nullif(v_sender->>'address', ''),\r\n      nullif(v_sender->>'city', ''), nullif(v_sender->>'postalCode', ''))), ''),\r\n    nullif(trim(coalesce(v_recipient->>'name', '')), ''),\r\n    nullif(trim(coalesce(v_recipient->>'phone', '')), ''),\r\n    nullif(trim(coalesce(v_recipient->>'address', '')), ''),\r\n    nullif(trim(coalesce(v_recipient->>'city', '')), ''),\r\n    coalesce(case when jsonb_typeof(v_invoice->'items') = 'array' then v_invoice->'items' end, '[]'::jsonb),\r\n    case when coalesce(v_ship.metadata->'collection'->>'selfCollection', 'false') = 'true'\r\n         then 'self_collection' else 'door_to_door' end,\r\n    v_paid >= v_total - 0.005 and v_total > 0,\r\n    greatest(0, v_total - v_paid),\r\n    current_date,\r\n    p_shipment_id,\r\n    v_actor\r\n  ) returning * into v_note;\r\n\r\n  insert into public.shipment_events(shipment_id, event_type, actor_id, details)\r\n  values (p_shipment_id, 'delivery_note_created', v_actor,\r\n          jsonb_build_object('reference', v_reference, 'invoiceNumber', v_invoice_number));\r\n\r\n  return jsonb_build_object('noteId', v_note.id, 'reference', v_note.reference, 'created', true);\r\nend $$;\r\n\r\nrevoke all on function public.create_shipment_delivery_note(uuid) from public, anon;\r\ngrant execute on function public.create_shipment_delivery_note(uuid) to authenticated;\r\n\r\n/**\r\n * The delivery notes raised against one collection period, with enough of the\r\n * shipment beside them to be read without a second query.\r\n *\r\n * Grouped the same way the shipments and invoices are, because the period is\r\n * how the business counts everything else.\r\n */\r\ncreate or replace function public.period_delivery_notes(p_period_id uuid)\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select case when not (public.is_operations_admin() or public.is_finance_staff() or public.is_staff_member())\r\n    then jsonb_build_object('error', 'Staff access required')\r\n    else coalesce((\r\n      select jsonb_agg(jsonb_build_object(\r\n        'noteId', n.id,\r\n        'reference', n.reference,\r\n        'invoiceNumber', n.invoice_number,\r\n        'noteDate', n.note_date,\r\n        'paid', n.paid,\r\n        'balanceDue', n.balance_due,\r\n        'deliveryMode', n.delivery_mode,\r\n        'voidedAt', n.voided_at,\r\n        'recipientName', n.recipient_name,\r\n        'recipientCity', n.recipient_city,\r\n        'items', n.items,\r\n        'createdAt', n.created_at,\r\n        'shipmentId', s.id,\r\n        'trackingNumber', s.tracking_number,\r\n        'customerReference', s.customer_reference,\r\n        'shipmentStatus', s.status,\r\n        'currency', coalesce(s.metadata->'invoice'->>'currency', 'GBP'),\r\n        'route', coalesce(cs.route, s.metadata->'collection'->>'route'),\r\n        'customerName', coalesce(\r\n          n.shipper_name,\r\n          s.metadata->'sender'->>'name',\r\n          trim(concat_ws(' ',\r\n            s.metadata->'sender'->>'firstName',\r\n            s.metadata->'sender'->>'lastName')))\r\n      ) order by n.created_at desc)\r\n      from public.delivery_note_records n\r\n      join public.shipments s on s.id = n.shipment_id\r\n      left join public.collection_schedules cs on cs.id = s.collection_schedule_id\r\n      where s.collection_period_id = p_period_id\r\n        and s.deleted_at is null\r\n    ), '[]'::jsonb)\r\n  end;\r\n$$;\r\n\r\nrevoke all on function public.period_delivery_notes(uuid) from public, anon;\r\ngrant execute on function public.period_delivery_notes(uuid) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Period totals count issued invoices only\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * The same summary as before, with two changes.\r\n *\r\n * \"Invoiced\" now means issued — an invoice number exists. A booking that has\r\n * been priced but not yet invoiced is no longer counted as money owed, because\r\n * nobody has asked the customer for it.\r\n *\r\n * `awaitingInvoice` is the count of shipments in that state, so the card says\r\n * how much work is waiting rather than quietly showing a smaller total.\r\n */\r\ncreate or replace function public.collection_period_summary()\r\nreturns jsonb\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select case when not (public.is_operations_admin() or public.is_finance_staff())\r\n    then jsonb_build_object('error', 'Admin or finance access required')\r\n    else coalesce((\r\n      select jsonb_agg(row order by row->>'sortKey' desc)\r\n      from (\r\n        select jsonb_build_object(\r\n          'periodId', p.id,\r\n          'name', p.name,\r\n          'month', p.month,\r\n          'year', p.year,\r\n          'status', p.status,\r\n          -- Sorted by the period's last scheduled collection, not by its\r\n          -- month name: `month` is text (\"May\", \"June\"), so anything\r\n          -- alphabetical puts April after August. Periods with nothing\r\n          -- scheduled yet fall back to their year.\r\n          'sortKey', coalesce(\r\n            to_char((select max(cs.pickup_on) from public.collection_schedules cs\r\n                     join public.collection_periods cp on cp.id = cs.collection_period_id\r\n                     where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n                       and cp.year = p.year), 'YYYY-MM-DD'),\r\n            lpad(coalesce(p.year, 0)::text, 4, '0') || '-00-00'),\r\n          -- Routes are matched on month and year, not only on the period id.\r\n          -- Live data has two September 2026 periods differing by nothing but\r\n          -- capitalisation: one holds every booking and no schedule, the other\r\n          -- every schedule and no booking. Matching on the id alone shows a\r\n          -- period full of work as having no routes at all.\r\n          'routes', coalesce((\r\n            select jsonb_agg(distinct cs.route)\r\n            from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year\r\n              and cs.route is not null and cs.deleted_at is null), '[]'::jsonb),\r\n          'firstCollection', (\r\n            select min(cs.pickup_on) from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year),\r\n          'lastCollection', (\r\n            select max(cs.pickup_on) from public.collection_schedules cs\r\n            join public.collection_periods cp on cp.id = cs.collection_period_id\r\n            where lower(trim(coalesce(cp.month, ''))) = lower(trim(coalesce(p.month, '')))\r\n              and cp.year = p.year),\r\n          'shipments', count(s.id),\r\n          'collected', count(s.id) filter (where lower(coalesce(s.status, '')) in\r\n            ('collected', 'at warehouse', 'enroute to zimbabwe', 'in transit', 'delivered')),\r\n          -- Priced by the booking, not yet raised by anybody.\r\n          'awaitingInvoice', count(s.id) filter (\r\n            where s.id is not null\r\n              and nullif(trim(coalesce(s.metadata->'invoice'->>'invoiceNumber', '')), '') is null),\r\n          -- Totals per currency, never added together: a period routinely\r\n          -- holds UK and Irish collections, and pounds plus euros is a number\r\n          -- that is not money in either.\r\n          'byCurrency', coalesce((\r\n            select jsonb_agg(jsonb_build_object(\r\n                     'currency', t.cur, 'invoiced', t.inv, 'paid', t.pd,\r\n                     'outstanding', greatest(0, t.inv - t.pd))\r\n                   order by t.inv desc)\r\n            from (\r\n              select coalesce(s2.metadata->'invoice'->>'currency', 'GBP') as cur,\r\n                sum(coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'items')='array'\r\n                                                    then s2.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n                    - coalesce((s2.metadata->'invoice'->>'discount')::numeric, 0)) as inv,\r\n                sum(coalesce((select sum(coalesce((pay->>'amount')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'payments')='array'\r\n                                                    then s2.metadata->'invoice'->'payments' else '[]'::jsonb end) pay), 0)) as pd\r\n              from public.shipments s2\r\n              where s2.collection_period_id = p.id and s2.deleted_at is null\r\n                -- A deleted invoice is not money owed. The screens filter it\r\n                -- out, so a period total that still counted it disagreed with\r\n                -- the list underneath it.\r\n                and s2.metadata->'invoice'->>'deletedAt' is null\r\n                -- Nor is one nobody has raised yet.\r\n                and nullif(trim(coalesce(s2.metadata->'invoice'->>'invoiceNumber', '')), '') is not null\r\n              group by 1\r\n              having sum(coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                     from jsonb_array_elements(case when jsonb_typeof(s2.metadata->'invoice'->'items')='array'\r\n                                                    then s2.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)) > 0\r\n            ) t), '[]'::jsonb),\r\n          'invoiced', coalesce(sum(inv.total), 0),\r\n          'paid', coalesce(sum(inv.paid), 0),\r\n          'outstanding', greatest(0, coalesce(sum(inv.total), 0) - coalesce(sum(inv.paid), 0)),\r\n          -- \"Cleared\" means nothing left to pay on that shipment.\r\n          'cleared', count(s.id) filter (where inv.total > 0 and inv.paid >= inv.total - 0.005),\r\n          'unpaid', count(s.id) filter (where inv.total > 0 and inv.paid <= 0.005),\r\n          'currency', coalesce(max(inv.currency), 'GBP')\r\n        ) as row\r\n        from public.collection_periods p\r\n        left join public.shipments s\r\n          on s.collection_period_id = p.id and s.deleted_at is null\r\n        left join lateral (\r\n          select\r\n            case when s.metadata->'invoice'->>'deletedAt' is not null\r\n                   or nullif(trim(coalesce(s.metadata->'invoice'->>'invoiceNumber', '')), '') is null then 0 else\r\n              coalesce((select sum(coalesce((i->>'quantity')::numeric,0) * coalesce((i->>'unitPrice')::numeric,0))\r\n                        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items')='array'\r\n                                                       then s.metadata->'invoice'->'items' else '[]'::jsonb end) i), 0)\r\n              - coalesce((s.metadata->'invoice'->>'discount')::numeric, 0) end as total,\r\n            case when s.metadata->'invoice'->>'deletedAt' is not null\r\n                   or nullif(trim(coalesce(s.metadata->'invoice'->>'invoiceNumber', '')), '') is null then 0 else\r\n              coalesce((select sum(coalesce((pay->>'amount')::numeric,0))\r\n                        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'payments')='array'\r\n                                                       then s.metadata->'invoice'->'payments' else '[]'::jsonb end) pay), 0) end as paid,\r\n            s.metadata->'invoice'->>'currency' as currency\r\n        ) inv on true\r\n        where p.deleted_at is null\r\n        group by p.id, p.name, p.month, p.year, p.status\r\n      ) grouped\r\n    ), '[]'::jsonb)\r\n  end;\r\n$$;\r\n\r\nrevoke all on function public.collection_period_summary() from public, anon;\r\ngrant execute on function public.collection_period_summary() to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. Bulk update can clear a field, not only set one\r\n-- ---------------------------------------------------------------------------\r\n\r\n/**\r\n * Same bulk update, plus the ability to say \"take this off its route\".\r\n *\r\n * The previous version wrote `coalesce(p_collection_schedule_id, s.collection_schedule_id)`,\r\n * so null meant \"leave it alone\" and there was no way to express \"remove it\".\r\n * That mattered in two places: taking a shipment off a route did nothing at\r\n * all, and moving one to another period silently kept the old period's route —\r\n * a September round attached to an October shipment, which no driver will ever\r\n * see and no report can explain.\r\n *\r\n * Clearing is now its own flag, so null keeps its meaning and callers that\r\n * predate this change behave exactly as before. Dropped and recreated rather\r\n * than overloaded, because two candidates both callable with four arguments\r\n * would make every existing call ambiguous.\r\n */\r\ndrop function if exists public.bulk_update_shipments(uuid[], text, uuid, uuid);\r\n\r\ncreate or replace function public.bulk_update_shipments(\r\n  p_ids uuid[],\r\n  p_status text default null,\r\n  p_collection_schedule_id uuid default null,\r\n  p_collection_period_id uuid default null,\r\n  p_clear_schedule boolean default false\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_count integer := 0;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Admin or finance access required' using errcode = '42501';\r\n  end if;\r\n  if p_ids is null or array_length(p_ids, 1) is null then\r\n    return jsonb_build_object('changed', 0);\r\n  end if;\r\n\r\n  update public.shipments s set\r\n    status = coalesce(nullif(trim(coalesce(p_status, '')), ''), s.status),\r\n    collection_schedule_id = case\r\n      when coalesce(p_clear_schedule, false) then null\r\n      else coalesce(p_collection_schedule_id, s.collection_schedule_id) end,\r\n    collection_period_id = coalesce(p_collection_period_id, s.collection_period_id),\r\n    updated_at = now()\r\n  where s.id = any(p_ids)\r\n    and s.deleted_at is null;\r\n\r\n  get diagnostics v_count = row_count;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'BULK_UPDATE', 'SHIPMENT', null,\r\n          jsonb_build_object('count', v_count, 'status', p_status,\r\n                             'scheduleId', p_collection_schedule_id,\r\n                             'clearedSchedule', coalesce(p_clear_schedule, false),\r\n                             'periodId', p_collection_period_id));\r\n\r\n  return jsonb_build_object('changed', v_count);\r\nend $$;\r\n\r\nrevoke all on function public.bulk_update_shipments(uuid[], text, uuid, uuid, boolean) from public, anon;\r\ngrant execute on function public.bulk_update_shipments(uuid[], text, uuid, uuid, boolean) to authenticated;\r\n\n\n-- One scoped feed for real drivers and admin preview; do not broaden shipment RLS.\ncreate or replace function public.driver_collection_feed(p_days integer default 7, p_start date default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_start date := coalesce(p_start, current_date); v_result jsonb;\nbegin\n  if not exists (select 1 from public.profiles where id = auth.uid()\n    and coalesce(staff_active, true)\n    and (is_admin or lower(role) in ('driver','admin','dispatcher','logistics','finance'))) then\n    raise exception 'Active staff access required' using errcode = '42501';\n  end if;\n  if p_days is null or p_days < 1 or p_days > 21 or v_start < current_date - 1 or v_start > current_date + 21 then\n    raise exception 'Choose a collection window of 1 to 21 days';\n  end if;\n  with bookings as (\n    select s.*, coalesce(s.metadata->'sender', s.metadata->'senderDetails', '{}'::jsonb) sender,\n      coalesce(public.parse_schedule_date(s.metadata->'collection'->>'date'),\n        public.parse_schedule_date(s.metadata->>'collectionDate'),\n        public.parse_schedule_date(cs.pickup_date),\n        (select min(public.parse_schedule_date(r.pickup_date)) from public.collection_schedules r\n          where r.approved is not false and nullif(trim(s.metadata->'collection'->>'route'),'') is not null\n          and regexp_replace(upper(trim(r.route)), '\\s+ROUTE$', '') = regexp_replace(upper(trim(s.metadata->'collection'->>'route')), '\\s+ROUTE$', '')\n          and public.parse_schedule_date(r.pickup_date) >= current_date)) pickup_day,\n      cs.country schedule_country\n    from public.shipments s left join public.collection_schedules cs on cs.id = s.collection_schedule_id\n    where s.deleted_at is null and lower(coalesce(s.collection_status,'')) <> 'collected'\n      and lower(coalesce(s.status,'')) not in ('collected','at warehouse','enroute to zimbabwe','delivered','cancelled','canceled')\n  ), rows as (\n    select b.pickup_day, jsonb_build_object(\n      'shipmentId',b.id,'trackingNumber',b.tracking_number,'customerReference',b.customer_reference,\n      'customerName',coalesce(nullif(trim(concat_ws(' ',b.sender->>'firstName',b.sender->>'lastName')),''),b.sender->>'name','Collection customer'),\n      'phone',b.sender->>'phone','address',b.sender->>'address','city',coalesce(b.sender->>'city',''),\n      'postcode',coalesce(b.sender->>'postcode',b.sender->>'postalCode',''),\n      'country',coalesce(nullif(trim(b.sender->>'country'),''),b.schedule_country,b.metadata->'collection'->>'country'),\n      'route',b.metadata->'collection'->>'route','goodsDescription',left(b.goods_description,400),\n      'collectionStatus',b.collection_status,'latitude',b.pickup_latitude,'longitude',b.pickup_longitude,\n      'stopId',case when c.driver_id = auth.uid() then c.stop_id end,\n      'claimId',c.id,'claimStatus',case when c.status in ('claimed','en_route','arrived') then c.status else 'available' end,\n      'claimedBy',coalesce(case when c.status in ('claimed','en_route','arrived') then c.driver_id end,b.assigned_driver_id),\n      'claimedByName',p.full_name,'claimedAt',c.claimed_at) item\n    from bookings b left join public.route_collection_claims c on c.shipment_id = b.id\n    left join public.profiles p on p.id = c.driver_id\n    where b.pickup_day >= v_start and b.pickup_day < v_start + p_days\n      -- Known overseas origins are not pickups. Missing/legacy country fields\n      -- remain usable when a collection date exists (e.g. a city in country).\n      and lower(trim(coalesce(b.sender->>'country',''))) not in ('zimbabwe','zw','south africa','za')\n  ), days as (\n    select pickup_day, jsonb_build_object('date',pickup_day,\n      'routes',coalesce(jsonb_agg(distinct item->>'route') filter (where nullif(trim(item->>'route'),'') is not null),'[]'::jsonb),\n      'collections',jsonb_agg(item order by item->>'city',item->>'customerName')) payload\n    from rows group by pickup_day\n  ) select coalesce(jsonb_agg(payload order by pickup_day),'[]'::jsonb) into v_result from days;\n  return v_result;\nend $$;\nrevoke all on function public.driver_collection_feed(integer,date) from public, anon;\ngrant execute on function public.driver_collection_feed(integer,date) to authenticated;\n\ncreate or replace function public.driver_route_collections(p_date date default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_day date := coalesce(p_date,current_date); v_feed jsonb;\nbegin\n  v_feed := public.driver_collection_feed(1,v_day);\n  return jsonb_build_object('date',v_day,'routes','[]'::jsonb,\n    'collections',coalesce(v_feed->0->'collections','[]'::jsonb));\nend $$;\nrevoke all on function public.driver_route_collections(date) from public, anon;\ngrant execute on function public.driver_route_collections(date) to authenticated;\n\n-- An unclaimed booking needs readable details before the driver claims it.\n-- Expose only operational fields, never customer handover codes or payments.\ncreate or replace function public.driver_collection_detail(p_shipment_id uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_feed jsonb; v_result jsonb;\nbegin\n  v_feed := public.driver_collection_feed(21,null);\n  if not exists (select 1 from jsonb_array_elements(v_feed) d,\n    jsonb_array_elements(d->'collections') c where c->>'shipmentId' = p_shipment_id::text) then\n    raise exception 'This booking is not in the upcoming collection window';\n  end if;\n  select jsonb_build_object('id',s.id,'tracking_number',s.tracking_number,'customer_reference',s.customer_reference,\n    'goods_description',s.goods_description,'collection_status',s.collection_status,'status',s.status,\n    'metadata',jsonb_build_object('sender',coalesce(s.metadata->'sender',s.metadata->'senderDetails'),\n      'recipient',coalesce(s.metadata->'recipient',s.metadata->'recipientDetails'),\n      'shipment',s.metadata->'shipment','shipmentDetails',s.metadata->'shipmentDetails',\n      'collection',s.metadata->'collection')) into v_result from public.shipments s where s.id = p_shipment_id;\n  return v_result;\nend $$;\nrevoke all on function public.driver_collection_detail(uuid) from public, anon;\ngrant execute on function public.driver_collection_detail(uuid) to authenticated;\n\n-- Pickup-only endpoint. Delivery continues to use the verified handover flow.\ncreate or replace function public.complete_driver_pickup(p_stop_id uuid, p_details_confirmed boolean, p_notes text default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_stop public.driver_run_stops%rowtype; v_ship public.shipments%rowtype; v_method text;\nbegin\n  if auth.uid() is null or not exists (select 1 from public.profiles where id = auth.uid()\n    and coalesce(staff_active,true) and (is_admin or lower(role) in ('driver','admin','dispatcher','logistics'))) then\n    raise exception 'Active driver access required' using errcode = '42501';\n  end if;\n  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;\n  if not found or v_stop.stop_type is distinct from 'collection' then raise exception 'Collection stop required'; end if;\n  if not exists (select 1 from public.driver_runs where id = v_stop.run_id and driver_id = auth.uid()) then\n    raise exception 'Stop is not assigned to you' using errcode = '42501';\n  end if;\n  -- A retry after a lost response must not create another event or change payment.\n  if v_stop.status = 'completed' then return jsonb_build_object('shipmentId',v_stop.shipment_id,'status','Collected','alreadyCompleted',true); end if;\n  if not exists (select 1 from public.driver_attendance where driver_id = auth.uid()\n    and work_date = current_date and clocked_in_at is not null and clocked_out_at is null) then\n    raise exception 'Clock in before completing a collection';\n  end if;\n  if v_stop.status <> 'arrived' then raise exception 'Mark arrived before completing the collection'; end if;\n  if p_details_confirmed is distinct from true then raise exception 'Confirm the customer, pickup address and goods first'; end if;\n  select * into v_ship from public.shipments where id = v_stop.shipment_id and deleted_at is null for update;\n  if not found then raise exception 'Shipment not found'; end if;\n  if v_ship.assigned_driver_id is not null and v_ship.assigned_driver_id <> auth.uid() then\n    raise exception 'Another driver is assigned to this shipment';\n  end if;\n  if lower(coalesce(v_ship.status,'')) in ('collected','at warehouse','enroute to zimbabwe','delivered','cancelled','canceled')\n    or lower(coalesce(v_ship.collection_status,'')) = 'collected' then raise exception 'This shipment is no longer awaiting collection'; end if;\n  v_method := case when v_stop.qr_verified_at is not null then 'qr'\n    when v_stop.code_verified_at is not null then 'code' else 'driver_confirmation' end;\n  update public.shipments set status = 'Collected', collection_status = 'Collected', driver_status = 'collected',\n    collected_at = now(), collected_by = auth.uid(), updated_at = now(),\n    metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('collectionHandover',jsonb_build_object(\n      'driverId',auth.uid(),'stopId',v_stop.id,'confirmedAt',now(),'verifiedBy',v_method,'notes',nullif(trim(p_notes),'')))\n    where id = v_ship.id;\n  update public.driver_run_stops set status = 'completed',completed_at = now(),updated_at = now() where id = v_stop.id;\n  update public.route_collection_claims set status = 'completed',completed_at = now(),updated_at = now()\n    where shipment_id = v_ship.id and driver_id = auth.uid();\n  insert into public.shipment_events(shipment_id,event_type,previous_status,new_status,actor_id,details)\n    values(v_ship.id,'collection_handover',v_ship.status,'Collected',auth.uid(),\n      jsonb_build_object('stopId',v_stop.id,'verifiedBy',v_method,'detailsConfirmed',true,'notes',p_notes));\n  if not exists (select 1 from public.driver_run_stops where run_id = v_stop.run_id and status not in ('completed','failed')) then\n    update public.driver_runs set status = 'completed',completed_at = now(),updated_at = now() where id = v_stop.run_id;\n  end if;\n  return jsonb_build_object('shipmentId',v_ship.id,'status','Collected','verifiedBy',v_method);\nend $$;\nrevoke all on function public.complete_driver_pickup(uuid,boolean,text) from public, anon;\ngrant execute on function public.complete_driver_pickup(uuid,boolean,text) to authenticated;\n\n\n-- A pickup can be visible in driver_route_collections because the booking\n-- carries today's collection date even when its old collection_schedule_id or\n-- route text no longer matches an active schedule row. Claiming must use the\n-- same source of truth as the feed, otherwise the Start collection button\n-- appears to do nothing for exactly the bookings the driver can see.\n\ncreate or replace function public.claim_route_collection(p_shipment_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_uid uuid := auth.uid();\n  v_ship public.shipments%rowtype;\n  v_claim public.route_collection_claims%rowtype;\n  v_run public.driver_runs%rowtype;\n  v_stop public.driver_run_stops%rowtype;\n  v_order integer;\n  v_route text;\n  v_address text;\n  v_name text;\nbegin\n  if v_uid is null then raise exception 'Sign in required'; end if;\n  if not exists (\n    select 1 from public.profiles p where p.id = v_uid\n      and coalesce(p.staff_active, true)\n      and (p.is_admin = true or lower(coalesce(p.role, '')) in ('driver', 'admin', 'dispatcher', 'logistics'))\n  ) then raise exception 'Active driver access required'; end if;\n\n  if not exists (\n    select 1 from public.driver_attendance a\n    where a.driver_id = v_uid and a.work_date = current_date and a.clocked_out_at is null\n  ) and not exists (\n    select 1 from public.profiles p where p.id = v_uid\n      and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics'))\n  ) then raise exception 'Clock in before claiming a collection'; end if;\n\n  select * into v_ship from public.shipments where id = p_shipment_id and deleted_at is null for update;\n  if not found then raise exception 'Shipment not found'; end if;\n  if coalesce(v_ship.collection_status, 'Awaiting Collection') = 'Collected' then\n    raise exception 'This shipment has already been collected';\n  end if;\n\n  -- Claim eligibility uses exactly the same date rules as the dashboard.\n  if not exists (select 1 from jsonb_array_elements(\n    public.driver_route_collections(null)->'collections') c\n    where c->>'shipmentId' = p_shipment_id::text) then\n    raise exception 'This shipment is not on today''s collection list';\n  end if;\n  if v_ship.assigned_driver_id is not null and v_ship.assigned_driver_id <> v_uid then\n    raise exception 'Another driver is assigned to this collection';\n  end if;\n\n  select * into v_claim from public.route_collection_claims where shipment_id = p_shipment_id for update;\n  if found and v_claim.status in ('claimed', 'en_route', 'arrived') and v_claim.driver_id <> v_uid then\n    select coalesce(p.full_name, 'Another driver') into v_name from public.profiles p where p.id = v_claim.driver_id;\n    raise exception '% is already working this collection', coalesce(v_name, 'Another driver');\n  end if;\n  if found and v_claim.driver_id = v_uid and v_claim.status in ('claimed', 'en_route', 'arrived') and v_claim.stop_id is not null then\n    return jsonb_build_object('claimId', v_claim.id, 'stopId', v_claim.stop_id, 'shipmentId', p_shipment_id, 'status', v_claim.status);\n  end if;\n\n  v_route := coalesce(v_ship.metadata->'collection'->>'route', 'Collection route');\n  v_address := concat_ws(', ', nullif(v_ship.metadata->'sender'->>'address', ''), nullif(v_ship.metadata->'sender'->>'city', ''),\n    nullif(coalesce(v_ship.metadata->'sender'->>'postcode', v_ship.metadata->'sender'->>'postalCode'), ''));\n\n  insert into public.driver_runs(driver_id, run_date, status, run_type, route_name, started_at)\n  values (v_uid, current_date, 'active', 'pickup', v_route, now())\n  on conflict(driver_id, run_date) do update set\n    status = 'active', run_type = 'pickup', route_name = coalesce(public.driver_runs.route_name, excluded.route_name),\n    started_at = coalesce(public.driver_runs.started_at, now()), completed_at = null, updated_at = now()\n  returning * into v_run;\n\n  select * into v_stop from public.driver_run_stops\n   where run_id = v_run.id and shipment_id = p_shipment_id limit 1 for update;\n  if found then\n    update public.driver_run_stops set status = 'planned', failure_reason = null, failure_note = null,\n      failed_at = null, en_route_at = null, arrived_at = null, completed_at = null, updated_at = now()\n    where id = v_stop.id returning * into v_stop;\n  else\n    select coalesce(max(stop_order), 0) + 1 into v_order from public.driver_run_stops where run_id = v_run.id;\n    insert into public.driver_run_stops(run_id, shipment_id, stop_order, stop_type, status, address,\n      latitude, longitude)\n    values (v_run.id, p_shipment_id, v_order, 'collection', 'planned', v_address,\n      v_ship.pickup_latitude, v_ship.pickup_longitude)\n    returning * into v_stop;\n  end if;\n\n  insert into public.route_collection_claims(shipment_id, schedule_id, driver_id, stop_id, claim_date, status, claimed_at, updated_at)\n  values (p_shipment_id, v_ship.collection_schedule_id, v_uid, v_stop.id, current_date, 'claimed', now(), now())\n  on conflict(shipment_id) do update set schedule_id = excluded.schedule_id, driver_id = excluded.driver_id,\n    stop_id = excluded.stop_id, claim_date = excluded.claim_date, status = 'claimed', claimed_at = now(),\n    en_route_at = null, arrived_at = null, completed_at = null, released_at = null,\n    issue_reason = null, issue_note = null, updated_at = now()\n  returning * into v_claim;\n\n  update public.shipments set assigned_driver_id = v_uid, driver_status = 'claimed', updated_at = now(),\n    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('driverUpdate', jsonb_build_object(\n      'status', 'claimed', 'driverId', v_uid, 'stopId', v_stop.id, 'updatedAt', now()))\n  where id = p_shipment_id;\n\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\n  values (p_shipment_id, 'collection_claimed', v_ship.driver_status, 'claimed', v_uid,\n    jsonb_build_object('claimId', v_claim.id, 'runId', v_run.id, 'stopId', v_stop.id));\n\n  return jsonb_build_object('claimId', v_claim.id, 'stopId', v_stop.id, 'shipmentId', p_shipment_id, 'status', 'claimed');\nend;\n$$;\n\ngrant execute on function public.claim_route_collection(uuid) to authenticated;\n\n-- At the address, begin the pickup in one transaction. Location and customer\n-- verification are optional, but clock-in, ownership and state are not.\ncreate or replace function public.begin_driver_pickup(p_shipment_id uuid)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare v_stop public.driver_run_stops%rowtype; v_claim jsonb;\nbegin\n  if not exists (select 1 from public.profiles where id = auth.uid() and coalesce(staff_active,true)\n    and (is_admin or lower(role) in ('driver','admin','dispatcher','logistics'))) then\n    raise exception 'Active driver access required' using errcode = '42501';\n  end if;\n  if not exists (select 1 from public.driver_attendance where driver_id = auth.uid()\n    and work_date = current_date and clocked_in_at is not null and clocked_out_at is null) then\n    raise exception 'Clock in before starting a collection';\n  end if;\n  select st.* into v_stop from public.driver_run_stops st join public.driver_runs r on r.id=st.run_id\n    where r.driver_id=auth.uid() and r.run_date=current_date and r.status <> 'cancelled'\n      and st.shipment_id=p_shipment_id and st.stop_type='collection' limit 1 for update of st;\n  if not found then\n    v_claim := public.claim_route_collection(p_shipment_id);\n    select * into v_stop from public.driver_run_stops where id=(v_claim->>'stopId')::uuid for update;\n  end if;\n  if v_stop.status not in ('planned','en_route','arrived') then raise exception 'This stop is already closed'; end if;\n  if v_stop.status='planned' then perform public.transition_driver_stop(v_stop.id,'en_route'); end if;\n  if v_stop.status <> 'arrived' then perform public.transition_driver_stop(v_stop.id,'arrived'); end if;\n  return jsonb_build_object('stopId',v_stop.id,'shipmentId',p_shipment_id,'status','arrived');\nend $$;\nrevoke all on function public.begin_driver_pickup(uuid) from public, anon;\ngrant execute on function public.begin_driver_pickup(uuid) to authenticated;\n\n";

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function getAdminClient() {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) throw new Error("Supabase service role is not configured");
  return createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
}

async function requireAdmin(req: Request) {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return null;
  const authClient = createClient(SUPABASE_URL, Deno.env.get("SUPABASE_ANON_KEY") || "", {
    global: { headers: { Authorization: authHeader } },
  });
  const { data: { user } } = await authClient.auth.getUser();
  if (!user) return null;
  const admin = getAdminClient();
  const { data: profile } = await admin.from("profiles").select("is_admin,role").eq("id", user.id).single();
  if (!profile || (!profile.is_admin && !["admin", "logistics"].includes(String(profile.role)))) return null;
  return user;
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  try {
    const body = await req.json().catch(() => ({}));
    const action = String(body?.action || "verify");

    if (!(await requireAdmin(req))) return json({ error: "Admin access required" }, 403);
    if (!SUPABASE_DB_URL) return json({ error: "SUPABASE_DB_URL is not available" }, 500);

    const sql = postgres(SUPABASE_DB_URL, { prepare: false });
    try {
      if (action === "setup") {
        if (!SETUP_SQL.trim()) {
          return json({ error: "SETUP_SQL is empty — run tools/embed-schema-setup-sql.cjs and redeploy" }, 500);
        }
        await sql.unsafe(SETUP_SQL);
        return json({ ok: true, message: "Schema is up to date.", chars: SETUP_SQL.length });
      }

      if (action === "verify") {
        // Every probe stands alone. This action's whole point is describing a
        // database that may not have been migrated yet, so a missing table or
        // column must read as "not there" rather than take the report down.
        const probe = async (sqlText: string, fallback: unknown) => {
          try {
            const [row] = await sql.unsafe(sqlText);
            return row ?? fallback;
          } catch {
            return fallback;
          }
        };

        const table = await probe(
          `select to_regclass('public.collection_slots') is not null as present`, { present: false });
        const dates = await probe(
          `select count(*) filter (where pickup_on is not null)::int as with_date, count(*)::int as total
             from public.collection_schedules`, { with_date: null, total: null });
        const unparsed = await probe(
          `select coalesce(string_agg(pickup_date, ' | '), '(none)') as samples
             from public.collection_schedules where pickup_on is null and coalesce(pickup_date,'') <> ''`,
          { samples: "n/a" });
        const job = await probe(
          `select count(*)::int as scheduled from cron.job where jobname = 'collection-slot-reminders'`,
          { scheduled: null });
        const functions = await probe(
          `select count(*)::int as present from pg_proc
            where proname in ('confirm_collection_slot','dispatch_set_collection_slot',
                              'mark_collection_customer_informed','queue_collection_slot_reminders')`,
          { present: 0 });
        const pickup = await probe(
          `select count(*) filter (where address_type = 'pickup')::int as pickup,
                  count(*) filter (where address_type = 'delivery')::int as delivery
             from public.customer_addresses`, { pickup: null, delivery: null });
        const drums = await probe(
          `select (value->>'metalDrumPurchase') as metal, (value->>'plasticDrumPurchase') as plastic
             from public.app_configuration where key = 'booking_fees'`, {});
        const booking = await probe(
          `select to_regprocedure('public.create_customer_booking_v2(jsonb)') is not null as wrapped`,
          { wrapped: false });

        const runs = await probe(
          `select count(*)::int as runs,
                  count(*) filter (where collection_date is not null)::int as dated
             from public.collection_runs`, { runs: null, dated: null });
        const filed = await probe(
          `select count(*) filter (where collection_run_id is not null)::int as filed,
                  count(*)::int as pending
             from public.shipments
            where deleted_at is null
              and lower(coalesce(status,'')) in ('booking confirmed','confirmed','pending')
              and created_at >= now() - interval '60 days'`, { filed: null, pending: null });

        return json({
          ok: true,
          collection_slots_table: table.present ?? false,
          collection_runs: `${runs.runs ?? "n/a"} runs (${runs.dated ?? "n/a"} dated)`,
          recent_pending_filed: `${filed.filed ?? "n/a"}/${filed.pending ?? "n/a"}`,
          schedules_with_parsed_date: `${dates.with_date ?? "n/a"}/${dates.total ?? "n/a"}`,
          unparsed_pickup_dates: unparsed.samples,
          rpcs_present: `${functions.present ?? 0}/4`,
          reminder_cron_scheduled: job.scheduled ?? "unknown",
          saved_addresses: `${pickup.pickup ?? "n/a"} pickup / ${pickup.delivery ?? "n/a"} delivery`,
          drum_purchase_prices: `metal ${drums.metal ?? "?"} / plastic ${drums.plastic ?? "?"}`,
          booking_fn_wrapped_for_drums: booking.wrapped ?? false,
        });
      }

      return json({ error: `Unknown action: ${action}` }, 400);
    } finally {
      await sql.end({ timeout: 5 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Unexpected error" }, 500);
  }
});
